        self.trade_log_csv = TRADE_LOG_CSV
        self.cycle_count = 0
        self.live_reject_telemetry = LiveRejectTelemetry(summary_interval_seconds=180.0, max_near_passes=10)
        self.live_positions = []
        self._live_order_timestamps = []
        self.live_execution_attempt_cooldowns = {}
        self.live_trade_day = None
        self.live_trade_count_today = 0
        self.aggressive_trade_day = None
        self.aggressive_trades_today = 0
        self.aggressive_trade_tickers = set()
