    def get_markets(self, limit=25, status="open", cursor=None, return_cursor=False, extra_params=None):
        if globals().get("LIVE_MODE", False):
            base_url = self.get_live_base_url()
            url = self.build_live_request_url("/trade-api/v2/markets")
            print(f"[LIVE-MARKETS-DEBUG] base_url={base_url}")
            print(f"[LIVE-MARKETS-DEBUG] url={url}")
        else:
            url = f"{BASE_URL}/markets"
        params = {
            "limit": limit,
            "status": status,
        }
        if cursor:
            params["cursor"] = cursor
        if extra_params:
            params.update(extra_params)
        if globals().get("LIVE_MODE", False):
            params.setdefault("mve_filter", "exclude")
        if globals().get("LIVE_MODE", False):
            print(f"[LIVE-MARKETS-DEBUG] params={params}")
        response = requests.get(url, params=params, timeout=15)
        response.raise_for_status()
        response_data = response.json()
        markets = response_data.get("markets", [])
        if return_cursor:
            next_cursor = response_data.get("cursor") or response_data.get("next_cursor")
            return markets, next_cursor
        return markets

    def to_float(self, value, default=0.0):
        try:
            if value is None:
                return default
            return float(value)
        except (TypeError, ValueError):
            return default

    def get_market_quote_values(self, market):
        return {
            "yes_bid": self.to_float(market.get("yes_bid_dollars", market.get("yes_bid")), None),
            "yes_ask": self.to_float(market.get("yes_ask_dollars", market.get("yes_ask")), None),
            "no_bid": self.to_float(market.get("no_bid_dollars", market.get("no_bid")), None),
            "no_ask": self.to_float(market.get("no_ask_dollars", market.get("no_ask")), None),
        }

    def has_complete_quote_side(self, bid_value, ask_value):
        return bid_value is not None and ask_value is not None

    def has_complete_numeric_quotes(self, market):
        quote_values = self.get_market_quote_values(market)
        return all(value is not None for value in quote_values.values())

    def _safe_payload_keys(self, payload):
        if not isinstance(payload, dict):
            return []
        return sorted(str(key) for key in payload.keys())[:30]

    def _is_sports_market_or_family(self, market_or_family):
        return self.get_market_discovery_category(market_or_family) == "sports"

    def is_sports_family(self, family, ticker=None):
        family = str(family or "").strip().upper()
        if not family and ticker:
            family = str(self.get_market_family({"ticker": str(ticker).strip()}) or "").strip().upper()
        sports_prefixes = ("KXNBA", "KXMLB", "KXNFL", "KXNHL", "KXNCAAB", "KXNCAAF")
        explicit_sports_families = {
            "KXNBA", "KXNBA1H", "KXNBA1HTOTAL", "KXNBA1HSPREAD", "KXNBASPREAD", "KXNBATOTAL",
            "KXMLB", "KXMLBSPREAD", "KXMLBTOTAL", "KXMLBHRR", "KXMLBMONEYLINE", "KXMLBHR", "KXMLBTB", "KXMLBHIT",
            "KXNFL", "KXNFLSPREAD", "KXNFLTOTAL",
            "KXNHL", "KXNHLGOAL",
            "KXNCAAB", "KXNCAAF",
        }
        if family in explicit_sports_families or any(family.startswith(prefix) for prefix in sports_prefixes):
            return True
        if ticker:
            ticker_family = str(self.get_market_family({"ticker": str(ticker).strip()}) or "").strip().upper()
            if ticker_family and (ticker_family in explicit_sports_families or any(ticker_family.startswith(prefix) for prefix in sports_prefixes)):
                return True
        return self.get_market_discovery_category(family or ticker or "") == "sports"

    def _get_sports_market_lifecycle_state(self, market=None, q=None, family=None, event_urgency=None):
        if sports_calibration is not None and hasattr(sports_calibration, "get_sports_market_lifecycle_state"):
            try:
                return sports_calibration.get_sports_market_lifecycle_state(bot=self, market=market, q=q, family=family, event_urgency=event_urgency)
            except Exception:
                pass
        market = market if isinstance(market, dict) else {}
        family = str(family or self.get_market_family(market) or "").strip().upper()
        if family == "KXBTC15M" or not self.is_sports_family(family, ticker=getattr(q, "ticker", None)):
            return "unknown"
        minutes_to_event = self.get_minutes_to_event(market)
        urgency = str(event_urgency or market.get("event_urgency") or market.get("urgency") or "").strip().lower()
        live_flag = bool(market.get("is_live") or market.get("live") or str(market.get("status") or market.get("market_status") or "").strip().lower() in {"live", "in_play", "open"})
        if minutes_to_event is None:
            if urgency in {"immediate", "near", "near_term", "urgent"}:
                return "live_early" if live_flag else "pregame_near"
            if urgency in {"far", "distant", "long_term"}:
                return "pregame_far"
            return "unknown"
        minutes_to_event = float(minutes_to_event)
        if live_flag:
            if minutes_to_event <= 15.0:
                return "live_late"
            if minutes_to_event <= 60.0:
                return "live_mid"
            return "live_early"
        if minutes_to_event > 240.0:
            return "pregame_far"
        if minutes_to_event > 45.0:
            return "pregame_near"
        if minutes_to_event >= 0.0:
            return "pregame_near"
        return "unknown"

    def compute_no_vig_probability(
        self,
        *,
        ticker=None,
        family=None,
        yes_bid=None,
        yes_ask=None,
        no_bid=None,
        no_ask=None,
        spread=None,
        market_lifecycle_state=None,
        event_urgency=None,
        liquidity_quality=None,
        quote_stability_trend=None,
        directional_consistency=None,
        orderbook_pressure=None,
        context="sports",
        market=None,
        q=None,
    ):
        if sports_calibration is not None and hasattr(sports_calibration, "compute_no_vig_probability"):
            try:
                return sports_calibration.compute_no_vig_probability(
                    bot=self,
                    ticker=ticker,
                    family=family,
                    yes_bid=yes_bid,
                    yes_ask=yes_ask,
                    no_bid=no_bid,
                    no_ask=no_ask,
                    spread=spread,
                    market_lifecycle_state=market_lifecycle_state,
                    event_urgency=event_urgency,
                    liquidity_quality=liquidity_quality,
                    quote_stability_trend=quote_stability_trend,
                    directional_consistency=directional_consistency,
                    orderbook_pressure=orderbook_pressure,
                    context=context,
                    market=market,
                    q=q,
                )
            except Exception:
                pass
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or market.get("ticker") or getattr(q, "ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        yes_bid = self.to_float(yes_bid, self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), None)))
        yes_ask = self.to_float(yes_ask, self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), None)))
        no_bid = self.to_float(no_bid, self.to_float(getattr(q, "no_bid", None), self.to_float(market.get("no_bid"), None)))
        no_ask = self.to_float(no_ask, self.to_float(getattr(q, "no_ask", None), self.to_float(market.get("no_ask"), None)))
        spread = max(0.0, self.to_float(spread, 0.0) or 0.0)
        yes_mid = None
        if yes_bid is not None and yes_ask is not None:
            yes_mid = max(0.0, min(1.0, (float(yes_bid) + float(yes_ask)) / 2.0))
        elif yes_bid is not None:
            yes_mid = max(0.0, min(1.0, float(yes_bid)))
        elif yes_ask is not None:
            yes_mid = max(0.0, min(1.0, float(yes_ask)))
        no_mid = None
        if no_bid is not None and no_ask is not None:
            no_mid = max(0.0, min(1.0, (float(no_bid) + float(no_ask)) / 2.0))
        elif no_bid is not None:
            no_mid = max(0.0, min(1.0, float(no_bid)))
        elif no_ask is not None:
            no_mid = max(0.0, min(1.0, float(no_ask)))
        if yes_mid is not None and no_mid is not None and (yes_mid + no_mid) > 0.0:
            yes_probability = max(0.01, min(0.99, yes_mid / max(yes_mid + no_mid, 0.0001)))
        elif yes_mid is not None:
            yes_probability = max(0.01, min(0.99, yes_mid))
        elif no_mid is not None:
            yes_probability = max(0.01, min(0.99, 1.0 - no_mid))
        else:
            yes_probability = 0.50
        quote_balance = 1.0
        if yes_mid is not None and no_mid is not None:
            quote_balance = max(0.25, min(1.25, 1.0 - abs(yes_mid - no_mid) * 0.55))
        spread_confidence = max(0.35, min(1.0, 1.0 - (spread * 2.25)))
        lifecycle_state = str(market_lifecycle_state or self._get_sports_market_lifecycle_state(market=market, q=q, family=family, event_urgency=event_urgency) or "unknown").strip().lower()
        lifecycle_confidence = {
            "pregame_far": 0.92,
            "pregame_near": 0.98,
            "live_early": 0.99,
            "live_mid": 1.00,
            "live_late": 0.93,
            "unknown": 0.88,
        }.get(lifecycle_state, 0.88)
        liquidity_quality = self._clamp(self.to_float(liquidity_quality, 0.5), 0.0, 1.0)
        quote_stability_trend = self._clamp(self.to_float(quote_stability_trend, 0.5), 0.0, 1.0)
        directional_consistency = self._clamp(self.to_float(directional_consistency, 0.5), 0.0, 1.0)
        orderbook_pressure = str(orderbook_pressure or "balanced").strip().lower()
        pressure_bias = {
            "yes_pressure": 0.03,
            "no_pressure": -0.03,
            "balanced": 0.0,
        }.get(orderbook_pressure, 0.0)
        stability_bias = (quote_stability_trend - 0.5) * 0.08 + (liquidity_quality - 0.5) * 0.06 + (directional_consistency - 0.5) * 0.05
        spread_bias = 0.0
        if spread <= 0.04:
            spread_bias += 0.02
        elif spread <= 0.08:
            spread_bias += 0.01
        elif spread > AION_SPORTS_MAX_SPREAD_SOFT:
            spread_bias -= 0.03
        if lifecycle_state in {"pregame_far", "live_late"}:
            spread_bias -= 0.015
        yes_probability = max(0.01, min(0.99, yes_probability))
        no_probability = max(0.01, min(0.99, 1.0 - yes_probability))
        no_vig_odds = 1.0 / max(yes_probability, 0.01)
        confidence = self._clamp((quote_balance * 0.30) + (spread_confidence * 0.25) + (lifecycle_confidence * 0.20) + (liquidity_quality * 0.15) + (quote_stability_trend * 0.10), 0.0, 1.0)
        return {
            "ticker": ticker or None,
            "family": family,
            "yes_probability": round(yes_probability, 4),
            "no_probability": round(no_probability, 4),
            "no_vig_probability": round(yes_probability, 4),
            "no_vig_odds": round(no_vig_odds, 6),
            "confidence": round(confidence, 4),
            "spread": round(spread, 4),
            "quote_balance": round(quote_balance, 4),
            "spread_confidence": round(spread_confidence, 4),
            "lifecycle_confidence": round(lifecycle_confidence, 4),
            "stability_bias": round(stability_bias + pressure_bias + spread_bias, 4),
            "orderbook_pressure": orderbook_pressure,
            "directional_consistency": round(directional_consistency, 4),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "liquidity_quality": round(liquidity_quality, 4),
            "market_lifecycle_state": lifecycle_state,
            "event_urgency": str(event_urgency or market.get("event_urgency") or market.get("urgency") or "unknown"),
            "context": context,
        }

    def compute_calibrated_sports_probability(
        self,
        *,
        ticker=None,
        family=None,
        no_vig_probability=None,
        momentum_score=None,
        directional_consistency=None,
        orderbook_pressure=None,
        repricing_velocity=None,
        spread_delta=None,
        quote_stability_trend=None,
        edge_durability_trend=None,
        family_learning_trend=None,
        predictive_regime_score=None,
        market_lifecycle_state=None,
        event_urgency=None,
        liquidity_quality=None,
        directional_bias=None,
        spread_bucket=None,
        context="sports",
        market=None,
        q=None,
    ):
        if sports_calibration is not None and hasattr(sports_calibration, "compute_calibrated_sports_probability"):
            try:
                return sports_calibration.compute_calibrated_sports_probability(
                    bot=self,
                    ticker=ticker,
                    family=family,
                    no_vig_probability=no_vig_probability,
                    momentum_score=momentum_score,
                    directional_consistency=directional_consistency,
                    orderbook_pressure=orderbook_pressure,
                    repricing_velocity=repricing_velocity,
                    spread_delta=spread_delta,
                    quote_stability_trend=quote_stability_trend,
                    edge_durability_trend=edge_durability_trend,
                    family_learning_trend=family_learning_trend,
                    predictive_regime_score=predictive_regime_score,
                    market_lifecycle_state=market_lifecycle_state,
                    event_urgency=event_urgency,
                    liquidity_quality=liquidity_quality,
                    directional_bias=directional_bias,
                    spread_bucket=spread_bucket,
                    context=context,
                    market=market,
                    q=q,
                )
            except Exception:
                pass
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or market.get("ticker") or getattr(q, "ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        base_probability = self._clamp(self.to_float(no_vig_probability, 0.5), 0.01, 0.99)
        momentum_score = self.to_float(momentum_score, 0.0) or 0.0
        directional_consistency = self._clamp(self.to_float(directional_consistency, 0.5), 0.0, 1.0)
        orderbook_pressure = str(orderbook_pressure or "balanced").strip().lower()
        repricing_velocity = self.to_float(repricing_velocity, 0.0) or 0.0
        spread_delta = self.to_float(spread_delta, 0.0) or 0.0
        quote_stability_trend = self._clamp(self.to_float(quote_stability_trend, 0.5), 0.0, 1.0)
        edge_durability_trend = self._clamp(self.to_float(edge_durability_trend, 0.5), 0.0, 1.0)
        family_learning_trend = self._clamp(self.to_float(family_learning_trend, 0.5), 0.0, 1.0)
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.5), 0.0, 1.0)
        liquidity_quality = self._clamp(self.to_float(liquidity_quality, 0.5), 0.0, 1.0)
        directional_bias = str(directional_bias or "unknown").strip().lower()
        spread_bucket = str(spread_bucket or "unknown").strip().lower()
        lifecycle_state = str(market_lifecycle_state or self._get_sports_market_lifecycle_state(market=market, q=q, family=family, event_urgency=event_urgency) or "unknown").strip().lower()
        signal_bias = 0.0
        signal_bias += (self._clamp(0.5 + momentum_score * 1.10, 0.0, 1.0) - 0.5) * 0.18
        signal_bias += (directional_consistency - 0.5) * 0.10
        pressure_bias = {
            "yes_pressure": 0.045,
            "no_pressure": -0.045,
            "balanced": 0.0,
        }.get(orderbook_pressure, 0.0)
        signal_bias += pressure_bias
        signal_bias += max(-0.04, min(0.04, repricing_velocity * 45.0))
        signal_bias += max(-0.03, min(0.03, spread_delta * 3.5))
        signal_bias += (quote_stability_trend - 0.5) * 0.08
        signal_bias += (edge_durability_trend - 0.5) * 0.06
        signal_bias += (family_learning_trend - 0.5) * 0.05
        signal_bias += (predictive_regime_score - 0.5) * 0.07
        signal_bias += (liquidity_quality - 0.5) * 0.05
        lifecycle_bias = {
            "pregame_far": -0.035,
            "pregame_near": 0.000,
            "live_early": 0.020,
            "live_mid": 0.030,
            "live_late": -0.025,
            "unknown": -0.020,
        }.get(lifecycle_state, -0.020)
        urgency_bias = {
            "high": 0.012,
            "normal": 0.006,
            "low": -0.004,
            "immediate": 0.015,
            "urgent": 0.014,
            "near": 0.010,
        }.get(str(event_urgency or market.get("event_urgency") or market.get("urgency") or "unknown").strip().lower(), 0.0)
        signal_bias += lifecycle_bias + urgency_bias
        if directional_bias == "flat" and spread_bucket in {"wide_but_possible", "extreme_wide"} and momentum_score < AION_SPORTS_MIN_MOMENTUM_FOR_WIDE:
            signal_bias -= 0.04
        calibration_before_family_bias = base_probability + signal_bias
        family_positive_bias = 0.0
        family_bias_reason = None
        if is_sports_family(family, ticker=ticker) and lifecycle_state in {"pregame_far", "pregame_near", "live_early"}:
            is_pregame_far = lifecycle_state == "pregame_far"
            if family.startswith(("KXNBA", "KXMLB", "KXNFL")):
                family_positive_bias += 0.002 if is_pregame_far else 0.003
                family_bias_reason = "strong_family"
            if spread_bucket in {"ultra_tight", "tight"}:
                family_positive_bias += 0.0015 if is_pregame_far else 0.002
                family_bias_reason = "tight_spread" if family_bias_reason is None else f"{family_bias_reason}+tight_spread"
            if calibration_before_family_bias - base_probability >= -0.005:
                family_positive_bias += 0.0015 if is_pregame_far else 0.002
                family_bias_reason = "near_positive_edge" if family_bias_reason is None else f"{family_bias_reason}+near_positive_edge"
            if calibration_before_family_bias >= base_probability - 0.015:
                family_positive_bias += 0.002 if is_pregame_far else 0.003
                family_bias_reason = "calibrated_prob_close_to_no_vig" if family_bias_reason is None else f"{family_bias_reason}+calibrated_prob_close_to_no_vig"
            elif calibration_before_family_bias >= base_probability:
                family_positive_bias += 0.0015 if is_pregame_far else 0.002
                family_bias_reason = "calibrated_prob_above_no_vig" if family_bias_reason is None else f"{family_bias_reason}+calibrated_prob_above_no_vig"
            family_positive_bias = min(family_positive_bias, 0.008 if is_pregame_far else 0.012)
        calibrated_probability = self._clamp(calibration_before_family_bias + family_positive_bias, 0.01, 0.99)
        return {
            "ticker": ticker or None,
            "family": family,
            "base_probability": round(base_probability, 4),
            "calibrated_probability_before_family_bias": round(calibration_before_family_bias, 4),
            "calibrated_probability": round(calibrated_probability, 4),
            "calibrated_probability_after_family_bias": round(calibrated_probability, 4),
            "signal_bias": round(signal_bias, 4),
            "family_positive_bias": round(family_positive_bias, 4),
            "family_bias_reason": family_bias_reason,
            "momentum_score": round(momentum_score, 4),
            "directional_consistency": round(directional_consistency, 4),
            "orderbook_pressure": orderbook_pressure,
            "repricing_velocity": round(repricing_velocity, 6),
            "spread_delta": round(spread_delta, 6),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "edge_durability_trend": round(edge_durability_trend, 4),
            "family_learning_trend": round(family_learning_trend, 4),
            "predictive_regime_score": round(predictive_regime_score, 4),
            "liquidity_quality": round(liquidity_quality, 4),
            "market_lifecycle_state": lifecycle_state,
            "event_urgency": str(event_urgency or market.get("event_urgency") or market.get("urgency") or "unknown"),
            "spread_bucket": spread_bucket,
            "context": context,
        }

    def compute_sports_dynamic_buffer(
        self,
        *,
        ticker=None,
        family=None,
        spread=None,
        spread_bucket=None,
        calibrated_probability=None,
        no_vig_probability=None,
        momentum_score=None,
        directional_consistency=None,
        orderbook_pressure=None,
        repricing_velocity=None,
        spread_delta=None,
        quote_stability_trend=None,
        edge_durability_trend=None,
        family_learning_trend=None,
        predictive_regime_score=None,
        liquidity_quality=None,
        market_lifecycle_state=None,
        event_urgency=None,
        estimated_cost=None,
        context="sports",
        market=None,
        q=None,
    ):
        if sports_calibration is not None and hasattr(sports_calibration, "compute_sports_dynamic_buffer"):
            try:
                result = sports_calibration.compute_sports_dynamic_buffer(
                    bot=self,
                    ticker=ticker,
                    family=family,
                    spread=spread,
                    spread_bucket=spread_bucket,
                    calibrated_probability=calibrated_probability,
                    no_vig_probability=no_vig_probability,
                    momentum_score=momentum_score,
                    directional_consistency=directional_consistency,
                    orderbook_pressure=orderbook_pressure,
                    repricing_velocity=repricing_velocity,
                    spread_delta=spread_delta,
                    quote_stability_trend=quote_stability_trend,
                    edge_durability_trend=edge_durability_trend,
                    family_learning_trend=family_learning_trend,
                    predictive_regime_score=predictive_regime_score,
                    liquidity_quality=liquidity_quality,
                    market_lifecycle_state=market_lifecycle_state,
                    event_urgency=event_urgency,
                    estimated_cost=estimated_cost,
                    context=context,
                    market=market,
                    q=q,
                )
                if isinstance(result, dict):
                    normalized = dict(result)
                    if "dynamic_buffer" not in normalized and "sports_dynamic_buffer" in normalized:
                        normalized["dynamic_buffer"] = normalized.get("sports_dynamic_buffer")
                    if "sports_dynamic_buffer" not in normalized and "dynamic_buffer" in normalized:
                        normalized["sports_dynamic_buffer"] = normalized.get("dynamic_buffer")
                    return normalized
                return result
            except Exception:
                pass
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or market.get("ticker") or getattr(q, "ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        spread = max(0.0, self.to_float(spread, 0.0) or 0.0)
        spread_bucket = str(spread_bucket or "unknown").strip().lower()
        calibrated_probability = self._clamp(self.to_float(calibrated_probability, 0.5), 0.01, 0.99)
        no_vig_probability = self._clamp(self.to_float(no_vig_probability, 0.5), 0.01, 0.99)
        momentum_score = self.to_float(momentum_score, 0.0) or 0.0
        directional_consistency = self._clamp(self.to_float(directional_consistency, 0.5), 0.0, 1.0)
        orderbook_pressure = str(orderbook_pressure or "balanced").strip().lower()
        repricing_velocity = self.to_float(repricing_velocity, 0.0) or 0.0
        spread_delta = self.to_float(spread_delta, 0.0) or 0.0
        quote_stability_trend = self._clamp(self.to_float(quote_stability_trend, 0.5), 0.0, 1.0)
        edge_durability_trend = self._clamp(self.to_float(edge_durability_trend, 0.5), 0.0, 1.0)
        family_learning_trend = self._clamp(self.to_float(family_learning_trend, 0.5), 0.0, 1.0)
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.5), 0.0, 1.0)
        liquidity_quality = self._clamp(self.to_float(liquidity_quality, 0.5), 0.0, 1.0)
        lifecycle_state = str(market_lifecycle_state or self._get_sports_market_lifecycle_state(market=market, q=q, family=family, event_urgency=event_urgency) or "unknown").strip().lower()
        estimated_cost = self._clamp(self.to_float(estimated_cost, 0.0), 0.0, 0.25)
        base_buffer = max(AION_SPORTS_MIN_EDGE_AFTER_COST, estimated_cost if estimated_cost > 0.0 else 0.01)
        instability_penalty = 0.0
        if spread_bucket in {"wide_but_possible", "extreme_wide"}:
            instability_penalty += 0.006 if spread_bucket == "wide_but_possible" else 0.014
        instability_penalty += max(0.0, (spread - 0.05) * 0.15)
        instability_penalty += max(0.0, (0.52 - quote_stability_trend) * 0.05)
        instability_penalty += max(0.0, (0.55 - liquidity_quality) * 0.05)
        instability_penalty += max(0.0, (0.50 - predictive_regime_score) * 0.04)
        instability_penalty += max(0.0, abs(repricing_velocity) * 18.0)
        instability_penalty += max(0.0, abs(spread_delta) * 3.0)
        if orderbook_pressure == "balanced":
            instability_penalty += 0.002
        elif orderbook_pressure == "no_pressure":
            instability_penalty += 0.006
        if lifecycle_state in {"pregame_far", "live_late"}:
            instability_penalty += 0.006
        if momentum_score < 0.0:
            instability_penalty += min(0.012, abs(momentum_score) * 0.02)
        stability_credit = 0.0
        stability_credit += max(0.0, (directional_consistency - 0.50) * 0.025)
        stability_credit += max(0.0, (quote_stability_trend - 0.50) * 0.04)
        stability_credit += max(0.0, (edge_durability_trend - 0.50) * 0.03)
        stability_credit += max(0.0, (family_learning_trend - 0.50) * 0.02)
        stability_credit += max(0.0, (calibrated_probability - no_vig_probability) * 0.02)
        lifecycle_discount = {
            "pregame_far": 0.004,
            "pregame_near": 0.0,
            "live_early": -0.002,
            "live_mid": -0.003,
            "live_late": 0.003,
            "unknown": 0.004,
        }.get(lifecycle_state, 0.004)
        urgency_penalty = {
            "high": 0.003,
            "normal": 0.001,
            "low": 0.0,
            "immediate": 0.004,
            "urgent": 0.004,
            "near": 0.002,
        }.get(str(event_urgency or market.get("event_urgency") or market.get("urgency") or "unknown").strip().lower(), 0.0)
        bucket_multiplier = {
            "ultra_tight": 0.82,
            "tight": 0.90,
            "medium": 1.00,
            "wide_but_possible": 1.14,
            "extreme_wide": 1.34,
            "unknown": 1.05,
        }.get(spread_bucket, 1.05)
        raw_buffer = (base_buffer + instability_penalty + urgency_penalty + lifecycle_discount - stability_credit) * bucket_multiplier
        if spread_bucket == "wide_but_possible" and quote_stability_trend >= 0.70 and liquidity_quality >= 0.62 and predictive_regime_score >= 0.55:
            raw_buffer *= 0.94
        if spread_bucket == "extreme_wide":
            raw_buffer = max(raw_buffer, 0.03)
        dynamic_buffer = self._clamp(raw_buffer, 0.004, 0.08)
        return {
            "ticker": ticker or None,
            "family": family,
            "dynamic_buffer": round(dynamic_buffer, 4),
            "base_buffer": round(base_buffer, 4),
            "instability_penalty": round(instability_penalty, 4),
            "stability_credit": round(stability_credit, 4),
            "bucket_multiplier": round(bucket_multiplier, 4),
            "lifecycle_discount": round(lifecycle_discount, 4),
            "urgency_penalty": round(urgency_penalty, 4),
            "spread_bucket": spread_bucket,
            "spread": round(spread, 4),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "edge_durability_trend": round(edge_durability_trend, 4),
            "family_learning_trend": round(family_learning_trend, 4),
            "predictive_regime_score": round(predictive_regime_score, 4),
            "liquidity_quality": round(liquidity_quality, 4),
            "market_lifecycle_state": lifecycle_state,
            "event_urgency": str(event_urgency or market.get("event_urgency") or market.get("urgency") or "unknown"),
            "context": context,
        }

    def compute_sports_post_cost_edge(
        self,
        *,
        ticker=None,
        family=None,
        calibrated_probability=None,
        no_vig_probability=None,
        no_vig_odds=None,
        dynamic_buffer=None,
        estimated_cost=None,
        spread_bucket=None,
        market_lifecycle_state=None,
        context="sports",
        market=None,
        q=None,
    ):
        def _extract_market_price(local_market, local_q):
            local_market = local_market if isinstance(local_market, dict) else {}
            candidates = (
                self.to_float(getattr(local_q, "yes_ask", None), None),
                self.to_float(local_market.get("yes_ask"), None),
                self.to_float(local_market.get("yes_ask_dollars"), None),
                self.to_float(getattr(local_q, "yes_bid", None), None),
                self.to_float(local_market.get("yes_bid"), None),
                self.to_float(local_market.get("yes_bid_dollars"), None),
            )
            for value in candidates:
                if value is not None and value > 0.0:
                    return self._clamp(value, 0.0, 1.0)
            yes_top_price = self._extract_orderbook_side_price_hint(local_market, "yes")
            if yes_top_price is not None and yes_top_price > 0.0:
                return self._clamp(yes_top_price, 0.0, 1.0)
            no_top_price = self._extract_orderbook_side_price_hint(local_market, "no")
            if no_top_price is not None and no_top_price > 0.0:
                return self._clamp(1.0 - no_top_price, 0.0, 1.0)
            no_side_candidates = (
                self.to_float(getattr(local_q, "no_bid", None), None),
                self.to_float(local_market.get("no_bid"), None),
                self.to_float(local_market.get("no_bid_dollars"), None),
                self.to_float(getattr(local_q, "no_ask", None), None),
                self.to_float(local_market.get("no_ask"), None),
                self.to_float(local_market.get("no_ask_dollars"), None),
            )
            for value in no_side_candidates:
                if value is not None and value > 0.0:
                    return self._clamp(1.0 - value, 0.0, 1.0)
            return None

        def _derive_edge_components(local_market, local_q):
            local_market = local_market if isinstance(local_market, dict) else {}
            yes_bid = self.to_float(getattr(local_q, "yes_bid", None), self.to_float(local_market.get("yes_bid"), None))
            yes_ask = self.to_float(getattr(local_q, "yes_ask", None), self.to_float(local_market.get("yes_ask"), None))
            no_bid = self.to_float(getattr(local_q, "no_bid", None), self.to_float(local_market.get("no_bid"), None))
            no_ask = self.to_float(getattr(local_q, "no_ask", None), self.to_float(local_market.get("no_ask"), None))
            if yes_bid is None or yes_ask is None or no_bid is None or no_ask is None:
                try:
                    fallback_quote = self.build_quote(local_market)
                except Exception:
                    fallback_quote = None
                if fallback_quote is not None:
                    fallback_yes_bid = self.to_float(getattr(fallback_quote, "yes_bid", None), None)
                    fallback_yes_ask = self.to_float(getattr(fallback_quote, "yes_ask", None), None)
                    fallback_no_bid = self.to_float(getattr(fallback_quote, "no_bid", None), None)
                    fallback_no_ask = self.to_float(getattr(fallback_quote, "no_ask", None), None)
                    if yes_bid is None and fallback_yes_bid is not None and fallback_yes_bid > 0.0:
                        yes_bid = fallback_yes_bid
                    if yes_ask is None and fallback_yes_ask is not None and fallback_yes_ask > 0.0:
                        yes_ask = fallback_yes_ask
                    if no_bid is None and fallback_no_bid is not None and fallback_no_bid > 0.0:
                        no_bid = fallback_no_bid
                    if no_ask is None and fallback_no_ask is not None and fallback_no_ask > 0.0:
                        no_ask = fallback_no_ask
            spread = None
            if yes_bid is not None and yes_ask is not None:
                try:
                    spread = max(0.0, float(yes_ask) - float(yes_bid))
                except (TypeError, ValueError):
                    spread = None
            if spread is None and no_bid is not None and no_ask is not None:
                try:
                    spread = max(0.0, float(no_ask) - float(no_bid))
                except (TypeError, ValueError):
                    spread = None
            if spread is None:
                yes_top_price = self._extract_orderbook_side_price_hint(local_market, "yes")
                no_top_price = self._extract_orderbook_side_price_hint(local_market, "no")
                if yes_top_price is not None and no_top_price is not None:
                    try:
                        spread = max(0.0, float(yes_top_price) + float(no_top_price) - 1.0)
                    except (TypeError, ValueError):
                        spread = None
            market_price = _extract_market_price(local_market, local_q)
            if market_price is None:
                if yes_ask is not None:
                    market_price = self._clamp(self.to_float(yes_ask, 0.0), 0.0, 1.0)
                elif no_bid is not None:
                    market_price = self._clamp(1.0 - self.to_float(no_bid, 0.0), 0.0, 1.0)
                else:
                    market_price = 0.5
            return market_price, spread, yes_bid, yes_ask, no_bid, no_ask

        if sports_calibration is not None and hasattr(sports_calibration, "compute_sports_post_cost_edge"):
            try:
                result = sports_calibration.compute_sports_post_cost_edge(
                    bot=self,
                    ticker=ticker,
                    family=family,
                    calibrated_probability=calibrated_probability,
                    no_vig_probability=no_vig_probability,
                    no_vig_odds=no_vig_odds,
                    dynamic_buffer=dynamic_buffer,
                    estimated_cost=estimated_cost,
                    spread_bucket=spread_bucket,
                    market_lifecycle_state=market_lifecycle_state,
                    context=context,
                    market=market,
                    q=q,
                )
                if isinstance(result, dict):
                    normalized = dict(result)
                    if "dynamic_buffer" not in normalized and "sports_dynamic_buffer" in normalized:
                        normalized["dynamic_buffer"] = normalized.get("sports_dynamic_buffer")
                    if "sports_dynamic_buffer" not in normalized and "dynamic_buffer" in normalized:
                        normalized["sports_dynamic_buffer"] = normalized.get("dynamic_buffer")
                    if "sports_edge_raw" not in normalized and "raw_edge" in normalized:
                        normalized["sports_edge_raw"] = normalized.get("raw_edge")
                    if "raw_edge" not in normalized and "sports_edge_raw" in normalized:
                        normalized["raw_edge"] = normalized.get("sports_edge_raw")
                    selector_edge_info = self._resolve_aion_selector_edge_value(
                        sports_context={
                            "final_edge": normalized.get("final_edge"),
                            "sports_edge_after_cost_after_family_bias": normalized.get("sports_edge_after_cost_after_family_bias"),
                            "sports_edge_after_cost": normalized.get("sports_edge_after_cost"),
                            "raw_edge_before_cost": normalized.get("sports_edge_raw"),
                            "spread_cost": normalized.get("dynamic_buffer"),
                            "estimated_cost": normalized.get("estimated_cost"),
                        }
                    )
                    normalized["selector_edge_used"] = selector_edge_info.get("selector_edge_used")
                    normalized["source_of_edge_value"] = selector_edge_info.get("source_of_edge_value")
                    normalized["selector_edge_floor"] = round(AION_SPORTS_MIN_EDGE_AFTER_COST, 6)
                    normalized["cost_buffer_used"] = round(
                        self.to_float(normalized.get("dynamic_buffer"), 0.0) + self.to_float(normalized.get("estimated_cost"), 0.0),
                        6,
                    )
                    normalized["edge_margin_to_floor"] = round(
                        self.to_float(normalized.get("selector_edge_used"), 0.0) - self.to_float(normalized.get("selector_edge_floor"), 0.0),
                        6,
                    )
                    raw_price, spread_value, yes_bid, yes_ask, no_bid, no_ask = _derive_edge_components(market, q)
                    expectancy_from_edge = self._clamp(
                        max(0.0, self.to_float(normalized.get("sports_edge_after_cost"), 0.0) / 0.08),
                        0.0,
                        1.0,
                    )
                    log_payload = {
                        "ticker": normalized.get("ticker") or ticker,
                        "family": normalized.get("family") or family,
                        "context": normalized.get("context") or context,
                        "raw_price": round(self.to_float(raw_price, 0.0), 4) if raw_price is not None else None,
                        "market_price": round(self.to_float(raw_price, 0.0), 4) if raw_price is not None else None,
                        "your_prob": normalized.get("calibrated_probability"),
                        "your_prob_before_family_bias": normalized.get("calibrated_probability_before_family_bias"),
                        "family_positive_bias": normalized.get("family_positive_bias"),
                        "spread": round(self.to_float(spread_value, 0.0), 4) if spread_value is not None else None,
                        "calibrated_probability": normalized.get("calibrated_probability"),
                        "no_vig_probability": normalized.get("no_vig_probability"),
                        "no_vig_odds": normalized.get("no_vig_odds"),
                        "dynamic_buffer": normalized.get("dynamic_buffer"),
                        "fees": normalized.get("estimated_cost"),
                        "estimated_cost": normalized.get("estimated_cost"),
                        "raw_edge_before_cost": normalized.get("sports_edge_raw"),
                        "sports_edge_after_cost_before_family_bias": normalized.get("sports_edge_after_cost_before_family_bias"),
                        "sports_edge_after_cost": normalized.get("sports_edge_after_cost"),
                        "sports_edge_after_cost_after_family_bias": normalized.get("sports_edge_after_cost_after_family_bias"),
                        "final_edge_before_family_bias": normalized.get("final_edge_before_family_bias"),
                        "final_edge": normalized.get("final_edge"),
                        "expectancy": round(expectancy_from_edge, 4),
                        "spread_bucket": normalized.get("spread_bucket"),
                        "market_lifecycle_state": normalized.get("market_lifecycle_state"),
                        "quote_missing": bool(yes_bid is None and yes_ask is None and no_bid is None and no_ask is None),
                        "quote_ready": bool(raw_price is not None and raw_price > 0.0 and (yes_bid is not None or yes_ask is not None or no_bid is not None or no_ask is not None)),
                    }
                    quote_readiness_diagnostic = self._diagnose_quote_readiness_context(
                        market=market,
                        q=q,
                        family=family,
                        sports_context=log_payload,
                        source=context,
                    )
                    market_lifecycle_state_value = str(normalized.get("market_lifecycle_state") or "unknown").strip().lower()
                    if self.to_float(normalized.get("final_edge"), 0.0) > 0.0 or self.to_float(normalized.get("sports_edge_after_cost"), 0.0) > 0.0:
                        quote_trace_payload = {
                            "ticker": normalized.get("ticker") or ticker,
                            "family": normalized.get("family") or family,
                            "final_edge": self.to_float(normalized.get("final_edge"), 0.0),
                            "sports_edge_after_cost": self.to_float(normalized.get("sports_edge_after_cost"), 0.0),
                            "quote_ready": bool(quote_readiness_diagnostic.get("quote_ready")),
                            "quote_ready_reason": quote_readiness_diagnostic.get("quote_ready_reason"),
                            "yes_bid": round(self.to_float(yes_bid, 0.0), 4) if yes_bid is not None else None,
                            "yes_ask": round(self.to_float(yes_ask, 0.0), 4) if yes_ask is not None else None,
                            "no_bid": round(self.to_float(no_bid, 0.0), 4) if no_bid is not None else None,
                            "no_ask": round(self.to_float(no_ask, 0.0), 4) if no_ask is not None else None,
                            "yes_top_size": quote_readiness_diagnostic.get("yes_top_size"),
                            "no_top_size": quote_readiness_diagnostic.get("no_top_size"),
                            "spread": quote_readiness_diagnostic.get("spread"),
                            "spread_bucket": quote_readiness_diagnostic.get("spread_bucket"),
                            "liquidity_depth": quote_readiness_diagnostic.get("liquidity_depth"),
                            "orderbook_age_seconds": quote_readiness_diagnostic.get("orderbook_age_seconds"),
                            "quote_stability_cycles": quote_readiness_diagnostic.get("quote_stability_cycles"),
                            "market_lifecycle_state": market_lifecycle_state_value,
                            "missing_quote_fields": quote_readiness_diagnostic.get("missing_quote_fields"),
                            "malformed_quote_fields": quote_readiness_diagnostic.get("malformed_quote_fields"),
                            "source_of_quote_data": quote_readiness_diagnostic.get("source_of_quote_data"),
                            "quote_ready_reason": quote_readiness_diagnostic.get("quote_ready_reason"),
                        }
                        print("[AION-QUOTE-READY-TRACE] " + json.dumps(quote_trace_payload, sort_keys=True, default=str))
                        if not bool(quote_readiness_diagnostic.get("quote_ready")):
                            print("[AION-QUOTE-READY-BLOCKER] " + json.dumps({
                                **quote_trace_payload,
                                "block_reason": quote_readiness_diagnostic.get("quote_ready_reason"),
                                "quote_ready_before_fallback": bool(quote_readiness_diagnostic.get("quote_ready_before_fallback")),
                                "quote_ready_after_fallback": bool(quote_readiness_diagnostic.get("quote_ready_after_fallback")),
                                "quote_missing_before_fallback": bool(quote_readiness_diagnostic.get("quote_missing_before_fallback")),
                                "quote_missing_after_fallback": bool(quote_readiness_diagnostic.get("quote_missing_after_fallback")),
                            }, sort_keys=True, default=str))
                        elif not bool(quote_readiness_diagnostic.get("quote_ready_before_fallback")) and bool(quote_readiness_diagnostic.get("quote_ready_after_fallback")):
                            print("[AION-QUOTE-READY-RECOVERED] " + json.dumps({
                                **quote_trace_payload,
                                "recovery_source": quote_readiness_diagnostic.get("source_of_quote_data"),
                                "quote_ready_before_fallback": bool(quote_readiness_diagnostic.get("quote_ready_before_fallback")),
                                "quote_ready_after_fallback": bool(quote_readiness_diagnostic.get("quote_ready_after_fallback")),
                            }, sort_keys=True, default=str))
                    print("[AION-EDGE-CALC] " + json.dumps(log_payload, sort_keys=True))
                    tune_suggestions = []
                    permanent_tune_payload = {
                        "ticker": normalized.get("ticker") or ticker,
                        "family": normalized.get("family") or family,
                        "context": normalized.get("context") or context,
                        "raw_price": round(self.to_float(raw_price, 0.0), 4) if raw_price is not None else None,
                        "market_price": round(self.to_float(raw_price, 0.0), 4) if raw_price is not None else None,
                        "spread": round(self.to_float(spread_value, 0.0), 4) if spread_value is not None else None,
                        "your_prob_before_family_bias": normalized.get("calibrated_probability_before_family_bias"),
                        "your_prob_after_family_bias": normalized.get("calibrated_probability"),
                        "dynamic_buffer": normalized.get("dynamic_buffer"),
                        "fees": normalized.get("estimated_cost"),
                        "raw_edge_before_cost": normalized.get("sports_edge_raw"),
                        "sports_edge_after_cost_before_family_bias": normalized.get("sports_edge_after_cost_before_family_bias"),
                        "sports_edge_after_cost_after_family_bias": normalized.get("sports_edge_after_cost_after_family_bias"),
                        "final_edge_before_family_bias": normalized.get("final_edge_before_family_bias"),
                        "final_edge_after_family_bias": normalized.get("final_edge"),
                        "family_positive_bias": normalized.get("family_positive_bias"),
                        "family_bias_reason": normalized.get("family_bias_reason"),
                        "spread_bucket": normalized.get("spread_bucket"),
                        "market_lifecycle_state": normalized.get("market_lifecycle_state"),
                        "suggested_improvements": tune_suggestions or ["keep_current_calibration"],
                    }
                    print("[AION-EDGE-PERMANENT-TUNE] " + json.dumps(permanent_tune_payload, sort_keys=True))
                    spread_value = self.to_float(spread_value, None)
                    spread_bucket_value = str(normalized.get("spread_bucket") or "unknown").strip().lower()
                    market_lifecycle_state_value = str(normalized.get("market_lifecycle_state") or "unknown").strip().lower()
                    calibrated_probability_value = self.to_float(normalized.get("calibrated_probability"), 0.0)
                    no_vig_probability_value = self.to_float(normalized.get("no_vig_probability"), 0.0)
                    sports_edge_after_cost_value = self.to_float(normalized.get("sports_edge_after_cost"), 0.0)
                    dynamic_buffer_value = self.to_float(normalized.get("dynamic_buffer"), 0.0)
                    if spread_bucket_value in {"ultra_tight", "tight"} and market_lifecycle_state_value in {"pregame_near", "live_early"}:
                        tune_suggestions.append("keep_pregame_bias_for_tight_books")
                    if spread_bucket_value in {"ultra_tight", "tight"} and spread_value is not None and spread_value <= 0.028:
                        tune_suggestions.append("retain_ultra_tight_relief_spread_limit=0.028")
                    if sports_edge_after_cost_value <= 0.0 and calibrated_probability_value > no_vig_probability_value:
                        tune_suggestions.append("trim_dynamic_buffer_for_good_signal")
                    if calibrated_probability_value <= no_vig_probability_value:
                        tune_suggestions.append("increase_probability_uplift_for_strong_signals")
                    if not tune_suggestions:
                        tune_suggestions.append("keep_current_calibration")
                    tune_payload = {
                        "ticker": normalized.get("ticker") or ticker,
                        "family": normalized.get("family") or family,
                        "context": normalized.get("context") or context,
                        "raw_price": round(self.to_float(raw_price, 0.0), 4) if raw_price is not None else None,
                        "market_price": round(self.to_float(raw_price, 0.0), 4) if raw_price is not None else None,
                        "spread": round(spread_value, 4) if spread_value is not None else None,
                        "your_prob": calibrated_probability_value,
                        "no_vig_probability": no_vig_probability_value,
                        "dynamic_buffer": dynamic_buffer_value,
                        "fees": self.to_float(normalized.get("estimated_cost"), 0.0),
                        "sports_edge_after_cost": sports_edge_after_cost_value,
                        "final_edge": self.to_float(normalized.get("final_edge"), max(0.0, sports_edge_after_cost_value)),
                        "spread_bucket": spread_bucket_value,
                        "market_lifecycle_state": market_lifecycle_state_value,
                        "ultra_tight_relief_spread_limit": 0.028,
                        "suggested_improvements": tune_suggestions,
                    }
                    print("[AION-EDGE-TUNE] " + json.dumps(tune_payload, sort_keys=True))
                    if self.to_float(normalized.get("final_edge"), 0.0) > 0.0 or self.to_float(normalized.get("sports_edge_after_cost"), 0.0) > 0.0:
                        print(
                            "[AION-POSITIVE-EDGE-TRACE] "
                            + json.dumps(
                                {
                                    "ticker": normalized.get("ticker") or ticker,
                                    "family": normalized.get("family") or family,
                                    "raw_edge_before_cost": normalized.get("sports_edge_raw"),
                                    "sports_edge_after_cost": normalized.get("sports_edge_after_cost"),
                                    "sports_edge_after_cost_after_family_bias": normalized.get("sports_edge_after_cost_after_family_bias"),
                                    "final_edge": normalized.get("final_edge"),
                                    "selector_edge_used": normalized.get("selector_edge_used"),
                                    "selector_edge_floor": normalized.get("selector_edge_floor"),
                                    "cost_buffer_used": normalized.get("cost_buffer_used"),
                                    "edge_margin_to_floor": normalized.get("edge_margin_to_floor"),
                                    "source_of_edge_value": normalized.get("source_of_edge_value"),
                                    "expectancy": self._clamp(
                                        max(0.0, self.to_float(normalized.get("sports_edge_after_cost"), 0.0) / 0.08),
                                        0.0,
                                        1.0,
                                    ),
                                    "quote_ready": bool(log_payload.get("quote_ready")),
                                    "phase55_ready": False,
                                    "fastpath_status": "unknown",
                                    "cooldown_status": "unknown",
                                    "duplicate_status": "unknown",
                                    "unsafe_price_status": "unknown",
                                    "final_gate_status": "score_only",
                                    "final_block_reason": None,
                                    "spread_bucket": spread_bucket_value,
                                    "market_lifecycle_state": market_lifecycle_state_value,
                                    "suggested_improvements": tune_suggestions,
                                },
                                sort_keys=True,
                                default=str,
                            )
                        )
                    normalized["quote_missing"] = log_payload["quote_missing"]
                    normalized["quote_ready"] = log_payload["quote_ready"]
                    return normalized
                return result
            except Exception:
                pass
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or market.get("ticker") or getattr(q, "ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        calibrated_probability = self._clamp(self.to_float(calibrated_probability, 0.5), 0.01, 0.99)
        no_vig_probability = self._clamp(self.to_float(no_vig_probability, 0.5), 0.01, 0.99)
        no_vig_odds = self.to_float(no_vig_odds, None)
        if no_vig_odds is None or no_vig_odds <= 0.0:
            no_vig_odds = 1.0 / max(no_vig_probability, 0.01)
        market_price = _extract_market_price(market, q)
        market_price_fallback_used = market_price is None
        if market_price is None:
            market_price = 0.5
        market_price = self._clamp(self.to_float(market_price, 0.5), 0.0, 1.0)
        _, spread_value, yes_bid, yes_ask, no_bid, no_ask = _derive_edge_components(market, q)
        spread_cost = self._clamp(
            self.to_float(dynamic_buffer, 0.01) if dynamic_buffer is not None else 0.0,
            0.0,
            0.20,
        )
        estimated_cost = self._clamp(self.to_float(estimated_cost, 0.0), 0.0, 0.25)
        raw_edge = calibrated_probability - market_price
        post_cost_edge_before_family_bias = self._clamp(raw_edge - spread_cost - estimated_cost, -0.25, 0.25)
        family_positive_bias = 0.0
        family_bias_reason = None
        strong_family = str(family or "").strip().upper().startswith(("KXNBA", "KXMLB", "KXNFL"))
        market_lifecycle_state_value = str(market_lifecycle_state or "unknown").strip().lower()
        spread_bucket_value = str(spread_bucket or "unknown").strip().lower()
        if market_lifecycle_state_value in {"pregame_far", "pregame_near", "live_early"}:
            is_pregame_far = market_lifecycle_state_value == "pregame_far"
            if strong_family:
                family_positive_bias += 0.002 if is_pregame_far else 0.003
                family_bias_reason = "strong_family"
            if spread_bucket_value in {"ultra_tight", "tight"}:
                family_positive_bias += 0.0015 if is_pregame_far else 0.002
                family_bias_reason = "tight_spread" if family_bias_reason is None else f"{family_bias_reason}+tight_spread"
            if post_cost_edge_before_family_bias >= -0.005:
                family_positive_bias += 0.0015 if is_pregame_far else 0.002
                family_bias_reason = "near_positive_edge" if family_bias_reason is None else f"{family_bias_reason}+near_positive_edge"
            if calibrated_probability >= no_vig_probability - 0.015:
                family_positive_bias += 0.002 if is_pregame_far else 0.003
                family_bias_reason = "calibrated_prob_close_to_no_vig" if family_bias_reason is None else f"{family_bias_reason}+calibrated_prob_close_to_no_vig"
            elif calibrated_probability >= no_vig_probability:
                family_positive_bias += 0.0015 if is_pregame_far else 0.002
                family_bias_reason = "calibrated_prob_above_no_vig" if family_bias_reason is None else f"{family_bias_reason}+calibrated_prob_above_no_vig"
            family_positive_bias = min(family_positive_bias, 0.008 if is_pregame_far else 0.012)
        final_edge_before_family_bias = max(0.0, post_cost_edge_before_family_bias)
        final_edge = self._clamp(final_edge_before_family_bias + family_positive_bias, 0.0, 0.25)
        selector_edge_info = self._resolve_aion_selector_edge_value(
            sports_context={
                "final_edge": final_edge,
                "sports_edge_after_cost_after_family_bias": final_edge,
                "sports_edge_after_cost": final_edge,
                "raw_edge_before_cost": raw_edge,
                "spread_cost": spread_cost,
                "estimated_cost": estimated_cost,
            }
        )
        selector_edge_used = self.to_float(selector_edge_info.get("selector_edge_used"), final_edge)
        selector_edge_floor = round(self.to_float(AION_SPORTS_MIN_EDGE_AFTER_COST, 0.0), 6)
        cost_buffer_used = round(self.to_float(spread_cost, 0.0) + self.to_float(estimated_cost, 0.0), 6)
        edge_margin_to_floor = round(selector_edge_used - selector_edge_floor, 6)
        log_payload = {
            "ticker": ticker or None,
            "family": family,
            "context": context,
            "calibrated_probability": round(calibrated_probability, 6),
            "calibrated_probability_before_family_bias": round(calibrated_probability, 6),
            "no_vig_probability": round(no_vig_probability, 6),
            "no_vig_odds": round(no_vig_odds, 6),
            "raw_price": round(market_price, 6),
            "market_price": round(market_price, 6),
            "spread": round(spread_value, 6) if spread_value is not None else None,
            "spread_cost": round(spread_cost, 6),
            "dynamic_buffer": round(spread_cost, 6),
            "estimated_cost": round(estimated_cost, 6),
            "fees": round(estimated_cost, 6),
            "raw_edge_before_cost": round(raw_edge, 6),
            "sports_edge_after_cost_before_family_bias": round(post_cost_edge_before_family_bias, 6),
            "sports_edge_after_cost": round(final_edge, 6),
            "sports_edge_after_cost_after_family_bias": round(final_edge, 6),
            "final_edge_before_family_bias": round(final_edge_before_family_bias, 6),
            "final_edge": round(final_edge, 6),
            "selector_edge_used": round(selector_edge_used, 6),
            "selector_edge_floor": selector_edge_floor,
            "cost_buffer_used": round(cost_buffer_used, 6),
            "edge_margin_to_floor": round(edge_margin_to_floor, 6),
            "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
            "family_positive_bias": round(family_positive_bias, 6),
            "family_bias_reason": family_bias_reason,
            "expectancy": round(max(0.0, final_edge / 0.08), 6),
            "spread_bucket": spread_bucket_value,
            "market_lifecycle_state": market_lifecycle_state_value,
            "quote_missing": bool(yes_bid is None and yes_ask is None and no_bid is None and no_ask is None),
            "quote_ready": bool(market_price is not None and market_price > 0.0 and (yes_bid is not None or yes_ask is not None or no_bid is not None or no_ask is not None)),
        }
        quote_readiness_diagnostic = self._diagnose_quote_readiness_context(
            market=market,
            q=q,
            family=family,
            sports_context=log_payload,
            source=context,
        )
        log_payload["quote_ready"] = bool(quote_readiness_diagnostic.get("quote_ready"))
        log_payload["quote_missing"] = bool(quote_readiness_diagnostic.get("quote_missing"))
        log_payload["quote_readiness_diagnostic"] = {k: v for k, v in quote_readiness_diagnostic.items() if k != "fallback_quote"}
        if self.to_float(final_edge, 0.0) > 0.0 or self.to_float(post_cost_edge_before_family_bias, 0.0) > 0.0:
            quote_trace_payload = {
                "ticker": ticker or None,
                "family": family,
                "final_edge": round(final_edge, 4),
                "sports_edge_after_cost": round(post_cost_edge_before_family_bias, 4),
                "quote_ready": bool(quote_readiness_diagnostic.get("quote_ready")),
                "quote_ready_reason": quote_readiness_diagnostic.get("quote_ready_reason"),
                "yes_bid": round(yes_bid, 4) if yes_bid is not None else None,
                "yes_ask": round(yes_ask, 4) if yes_ask is not None else None,
                "no_bid": round(no_bid, 4) if no_bid is not None else None,
                "no_ask": round(no_ask, 4) if no_ask is not None else None,
                "yes_top_size": quote_readiness_diagnostic.get("yes_top_size"),
                "no_top_size": quote_readiness_diagnostic.get("no_top_size"),
                "spread": quote_readiness_diagnostic.get("spread"),
                "spread_bucket": quote_readiness_diagnostic.get("spread_bucket"),
                "liquidity_depth": quote_readiness_diagnostic.get("liquidity_depth"),
                "orderbook_age_seconds": quote_readiness_diagnostic.get("orderbook_age_seconds"),
                "quote_stability_cycles": quote_readiness_diagnostic.get("quote_stability_cycles"),
                "market_lifecycle_state": market_lifecycle_state_value,
                "missing_quote_fields": quote_readiness_diagnostic.get("missing_quote_fields"),
                "malformed_quote_fields": quote_readiness_diagnostic.get("malformed_quote_fields"),
                "source_of_quote_data": quote_readiness_diagnostic.get("source_of_quote_data"),
                "quote_ready_reason": quote_readiness_diagnostic.get("quote_ready_reason"),
            }
            print("[AION-QUOTE-READY-TRACE] " + json.dumps(quote_trace_payload, sort_keys=True, default=str))
            if not bool(quote_readiness_diagnostic.get("quote_ready")):
                print("[AION-QUOTE-READY-BLOCKER] " + json.dumps({
                    **quote_trace_payload,
                    "block_reason": quote_readiness_diagnostic.get("quote_ready_reason"),
                    "quote_ready_before_fallback": bool(quote_readiness_diagnostic.get("quote_ready_before_fallback")),
                    "quote_ready_after_fallback": bool(quote_readiness_diagnostic.get("quote_ready_after_fallback")),
                    "quote_missing_before_fallback": bool(quote_readiness_diagnostic.get("quote_missing_before_fallback")),
                    "quote_missing_after_fallback": bool(quote_readiness_diagnostic.get("quote_missing_after_fallback")),
                }, sort_keys=True, default=str))
            elif not bool(quote_readiness_diagnostic.get("quote_ready_before_fallback")) and bool(quote_readiness_diagnostic.get("quote_ready_after_fallback")):
                print("[AION-QUOTE-READY-RECOVERED] " + json.dumps({
                    **quote_trace_payload,
                    "recovery_source": quote_readiness_diagnostic.get("source_of_quote_data"),
                    "quote_ready_before_fallback": bool(quote_readiness_diagnostic.get("quote_ready_before_fallback")),
                    "quote_ready_after_fallback": bool(quote_readiness_diagnostic.get("quote_ready_after_fallback")),
                }, sort_keys=True, default=str))
        print("[AION-EDGE-CALC] " + json.dumps(log_payload, sort_keys=True, default=str))
        return {
            "ticker": ticker or None,
            "family": family,
            "calibrated_probability_before_family_bias": round(max(0.0, calibrated_probability - family_positive_bias), 4),
            "calibrated_probability_after_family_bias": round(calibrated_probability, 4),
            "calibrated_probability": round(calibrated_probability, 4),
            "no_vig_probability": round(no_vig_probability, 4),
            "no_vig_odds": round(no_vig_odds, 6),
            "sports_edge_raw": round(raw_edge, 4),
            "sports_edge_after_cost_before_family_bias": round(post_cost_edge_before_family_bias, 4),
            "sports_edge_after_cost": round(final_edge, 4),
            "sports_edge_after_cost_after_family_bias": round(final_edge, 4),
            "final_edge_before_family_bias": round(final_edge_before_family_bias, 4),
            "final_edge": round(final_edge, 4),
            "selector_edge_used": round(selector_edge_used, 4),
            "selector_edge_floor": round(selector_edge_floor, 4),
            "cost_buffer_used": round(cost_buffer_used, 4),
            "edge_margin_to_floor": round(edge_margin_to_floor, 4),
            "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
            "dynamic_buffer": round(spread_cost, 4),
            "spread_cost": round(spread_cost, 4),
            "estimated_cost": round(estimated_cost, 4),
            "raw_price": round(market_price, 4),
            "spread_bucket": spread_bucket_value,
            "market_lifecycle_state": market_lifecycle_state_value,
            "context": context,
            "quote_missing": log_payload["quote_missing"],
            "quote_ready": log_payload["quote_ready"],
            "family_positive_bias": round(family_positive_bias, 4),
            "family_bias_reason": family_bias_reason,
            "selector_edge_used": round(selector_edge_used, 4),
            "selector_edge_floor": round(selector_edge_floor, 4),
            "cost_buffer_used": round(cost_buffer_used, 4),
            "edge_margin_to_floor": round(edge_margin_to_floor, 4),
            "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
        }

    def compute_sports_spread_context(
        self,
        *,
        ticker=None,
        family=None,
        yes_bid=None,
        yes_ask=None,
        no_bid=None,
        no_ask=None,
        spread=None,
        yes_top_size=None,
        no_top_size=None,
        open_interest=None,
        event_urgency=None,
        market_lifecycle_state=None,
        momentum_score=None,
        directional_bias=None,
        predictive_regime_score=None,
        edge_score=None,
        estimated_cost=None,
        market=None,
        q=None,
        volume=None,
        quote_stability=None,
        predictive_regime_state=None,
        directional_consistency=None,
        orderbook_pressure=None,
        repricing_velocity=None,
        spread_delta=None,
        quote_stability_trend=None,
        edge_durability_trend=None,
        family_learning_trend=None,
        liquidity_quality=None,
        adaptive_confidence_modifier=None,
        family_rotation_score=None,
        entry_timing_fusion_score=None,
        queue_state=None,
    ):
        market = market if isinstance(market, dict) else {}
        ticker = str(ticker or market.get("ticker") or getattr(q, "ticker", "") or "").strip()
        family = str(family or self.get_market_family(market) or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        is_sports = self.is_sports_family(family, ticker=ticker)
        sports_quote_snapshot = {}
        if is_sports:
            try:
                sports_quote_snapshot = self._extract_non_targeted_topbook_snapshot(market)
            except Exception as exc:
                sports_quote_snapshot = {
                    "failure_stage": "topbook_snapshot_exception",
                    "failure_reason": exc.__class__.__name__,
                }

        def _normalize_sports_price(value):
            numeric = self.to_float(value, None)
            if numeric is None or numeric <= 0.0:
                return None
            return numeric

        yes_bid_raw = self.to_float(yes_bid, self.to_float(getattr(q, "yes_bid", None), self.to_float(market.get("yes_bid"), None)))
        yes_ask_raw = self.to_float(yes_ask, self.to_float(getattr(q, "yes_ask", None), self.to_float(market.get("yes_ask"), None)))
        no_bid_raw = self.to_float(no_bid, self.to_float(getattr(q, "no_bid", None), self.to_float(market.get("no_bid"), None)))
        no_ask_raw = self.to_float(no_ask, self.to_float(getattr(q, "no_ask", None), self.to_float(market.get("no_ask"), None)))
        yes_bid = _normalize_sports_price(yes_bid_raw)
        yes_ask = _normalize_sports_price(yes_ask_raw)
        no_bid = _normalize_sports_price(no_bid_raw)
        no_ask = _normalize_sports_price(no_ask_raw)
        quote_fields_before_mapping = {
            "yes_bid": yes_bid,
            "yes_ask": yes_ask,
            "no_bid": no_bid,
            "no_ask": no_ask,
        }
        source_quote_fields_present = sorted(
            [
                name
                for name, value in {
                    "yes_bid_dollars": market.get("yes_bid_dollars"),
                    "yes_ask_dollars": market.get("yes_ask_dollars"),
                    "no_bid_dollars": market.get("no_bid_dollars"),
                    "no_ask_dollars": market.get("no_ask_dollars"),
                    "best_yes_price": market.get("best_yes_price"),
                    "best_no_price": market.get("best_no_price"),
                    "yes_top_price": sports_quote_snapshot.get("yes_top_price"),
                    "no_top_price": sports_quote_snapshot.get("no_top_price"),
                    "orderbook": market.get("orderbook"),
                    "orderbook_fp": market.get("orderbook_fp"),
                    "yes_dollars": market.get("yes_dollars"),
                    "no_dollars": market.get("no_dollars"),
                    "yes": market.get("yes"),
                    "no": market.get("no"),
                }.items()
                if value not in (None, "", [], {})
            ]
        )
        source_quote_fields_missing = sorted(
            [name for name in ("yes_bid_dollars", "yes_ask_dollars", "no_bid_dollars", "no_ask_dollars") if not _normalize_sports_price(market.get(name))]
        )
        quote_mapping_applied = False
        quote_mapping_reason = "direct_fields"
        quote_mapping_block_reason = None
        yes_top_price = self.to_float(sports_quote_snapshot.get("yes_top_price"), None)
        no_top_price = self.to_float(sports_quote_snapshot.get("no_top_price"), None)
        if is_sports:
            if yes_ask is None and yes_top_price is not None and yes_top_price > 0.0:
                yes_ask = yes_top_price
                quote_mapping_applied = True
                quote_mapping_reason = "yes_top_price_fallback"
            if no_ask is None and no_top_price is not None and no_top_price > 0.0:
                no_ask = no_top_price
                quote_mapping_applied = True
                quote_mapping_reason = "no_top_price_fallback"
            if yes_bid is None and no_ask is not None:
                yes_bid = max(0.0, 1.0 - float(no_ask))
                quote_mapping_applied = True
                quote_mapping_reason = "paired_topbook_recovery"
            if no_bid is None and yes_ask is not None:
                no_bid = max(0.0, 1.0 - float(yes_ask))
                quote_mapping_applied = True
                quote_mapping_reason = "paired_topbook_recovery"
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)
            if (
                yes_bid is None
                and yes_ask is None
                and no_bid is None
                and no_ask is None
                and (yes_top_price is None or yes_top_price <= 0.0)
                and (no_top_price is None or no_top_price <= 0.0)
            ):
                quote_mapping_block_reason = "no_valid_quote_or_orderbook_prices"
            if yes_bid is None or yes_ask is None or no_bid is None or no_ask is None:
                try:
                    fallback_quote = self.build_quote(market)
                except Exception:
                    fallback_quote = None
                if fallback_quote is not None:
                    fallback_yes_bid = self.to_float(getattr(fallback_quote, "yes_bid", None), None)
                    fallback_yes_ask = self.to_float(getattr(fallback_quote, "yes_ask", None), None)
                    fallback_no_bid = self.to_float(getattr(fallback_quote, "no_bid", None), None)
                    fallback_no_ask = self.to_float(getattr(fallback_quote, "no_ask", None), None)
                    if yes_bid is None and fallback_yes_bid is not None and fallback_yes_bid > 0.0:
                        yes_bid = fallback_yes_bid
                        quote_mapping_applied = True
                        quote_mapping_reason = "build_quote_fallback"
                    if yes_ask is None and fallback_yes_ask is not None and fallback_yes_ask > 0.0:
                        yes_ask = fallback_yes_ask
                        quote_mapping_applied = True
                        quote_mapping_reason = "build_quote_fallback"
                    if no_bid is None and fallback_no_bid is not None and fallback_no_bid > 0.0:
                        no_bid = fallback_no_bid
                        quote_mapping_applied = True
                        quote_mapping_reason = "build_quote_fallback"
                    if no_ask is None and fallback_no_ask is not None and fallback_no_ask > 0.0:
                        no_ask = fallback_no_ask
                        quote_mapping_applied = True
                        quote_mapping_reason = "build_quote_fallback"
        else:
            yes_bid, yes_ask, no_bid, no_ask = self._infer_missing_binary_quotes(yes_bid, yes_ask, no_bid, no_ask)
        spread = self.to_float(spread, None)
        if spread is None and yes_bid is not None and yes_ask is not None:
            spread = max(0.0, float(yes_ask) - float(yes_bid))
        spread = max(0.0, self.to_float(spread, 0.0) or 0.0)
        yes_top_size = self.to_float(yes_top_size, self.to_float(market.get("yes_top_size"), None))
        no_top_size = self.to_float(no_top_size, self.to_float(market.get("no_top_size"), None))
        top_sizes = [size for size in (yes_top_size, no_top_size) if size is not None and size > 0.0]
        max_top_size = max(top_sizes) if top_sizes else 0.0
        min_top_size = min(top_sizes) if len(top_sizes) == 2 else 0.0
        open_interest = self.to_float(open_interest, self.to_float(market.get("open_interest_fp", market.get("open_interest")), 0.0) or 0.0)
        volume = self.to_float(volume, self.to_float(market.get("volume_fp", market.get("volume")), 0.0) or 0.0)
        market_lifecycle_state = str(market_lifecycle_state or self._get_sports_market_lifecycle_state(market=market, q=q, family=family, event_urgency=event_urgency) or "unknown").strip().lower()
        momentum_score = self.to_float(momentum_score, 0.0) or 0.0
        directional_bias = str(directional_bias or "unknown").strip().lower()
        predictive_regime_score = self._clamp(self.to_float(predictive_regime_score, 0.0))
        quote_stability = self._clamp(self.to_float(quote_stability, 0.0))
        estimated_cost = self._clamp(self.to_float(estimated_cost, 0.0))
        sports_edge_score = self._clamp(self.to_float(edge_score, 0.0))
        edge_score_norm = self._clamp(min(1.0, sports_edge_score / 100.0))
        directional_consistency = self._clamp(self.to_float(directional_consistency, 0.5), 0.0, 1.0)
        liquidity_quality = self._clamp(self.to_float(liquidity_quality, 0.5), 0.0, 1.0)
        quote_stability_trend = self._clamp(self.to_float(quote_stability_trend, quote_stability if quote_stability is not None else 0.5), 0.0, 1.0)
        edge_durability_trend = self._clamp(self.to_float(edge_durability_trend, 0.5), 0.0, 1.0)
        family_learning_trend = self._clamp(self.to_float(family_learning_trend, 0.5), 0.0, 1.0)
        adaptive_confidence_modifier = self.to_float(adaptive_confidence_modifier, 0.0) or 0.0
        family_rotation_score = self.to_float(family_rotation_score, 0.0) or 0.0
        entry_timing_fusion_score = self.to_float(entry_timing_fusion_score, 0.0) or 0.0
        queue_state = str(queue_state or "unknown").strip().lower()
        estimated_spread_cost = self._clamp(max(0.0, spread * 0.45))
        estimated_fee_cost = self._clamp(max(0.005, estimated_cost if estimated_cost > 0.0 else 0.01))
        no_vig_summary = self.compute_no_vig_probability(
            ticker=ticker,
            family=family,
            yes_bid=yes_bid,
            yes_ask=yes_ask,
            no_bid=no_bid,
            no_ask=no_ask,
            spread=spread,
            market_lifecycle_state=market_lifecycle_state,
            event_urgency=event_urgency,
            liquidity_quality=liquidity_quality,
            quote_stability_trend=quote_stability_trend,
            directional_consistency=directional_consistency,
            orderbook_pressure=orderbook_pressure,
            market=market,
            q=q,
            context="sports_context",
        )
        calibrated_probability_summary = self.compute_calibrated_sports_probability(
            ticker=ticker,
            family=family,
            no_vig_probability=no_vig_summary.get("no_vig_probability"),
            momentum_score=momentum_score,
            directional_consistency=directional_consistency,
            orderbook_pressure=orderbook_pressure if isinstance(orderbook_pressure, str) else sports_momentum.get("orderbook_pressure"),
            repricing_velocity=repricing_velocity if repricing_velocity is not None else self.to_float(sports_momentum.get("repricing_velocity"), 0.0),
            spread_delta=spread_delta if spread_delta is not None else self.to_float(sports_momentum.get("spread_delta"), 0.0),
            quote_stability_trend=quote_stability_trend,
            edge_durability_trend=edge_durability_trend,
            family_learning_trend=family_learning_trend,
            predictive_regime_score=predictive_regime_score,
            market_lifecycle_state=market_lifecycle_state,
            event_urgency=event_urgency,
            liquidity_quality=liquidity_quality,
            directional_bias=directional_bias,
            spread_bucket="unknown",
            market=market,
            q=q,
            context="sports_context",
        )
        dynamic_buffer_summary = self.compute_sports_dynamic_buffer(
            ticker=ticker,
            family=family,
            spread=spread,
            spread_bucket="unknown",
            calibrated_probability=calibrated_probability_summary.get("calibrated_probability"),
            no_vig_probability=no_vig_summary.get("no_vig_probability"),
            momentum_score=momentum_score,
            directional_consistency=directional_consistency,
            orderbook_pressure=orderbook_pressure if isinstance(orderbook_pressure, str) else sports_momentum.get("orderbook_pressure"),
            repricing_velocity=repricing_velocity if repricing_velocity is not None else self.to_float(sports_momentum.get("repricing_velocity"), 0.0),
            spread_delta=spread_delta if spread_delta is not None else self.to_float(sports_momentum.get("spread_delta"), 0.0),
            quote_stability_trend=quote_stability_trend,
            edge_durability_trend=edge_durability_trend,
            family_learning_trend=family_learning_trend,
            predictive_regime_score=predictive_regime_score,
            liquidity_quality=liquidity_quality,
            market_lifecycle_state=market_lifecycle_state,
            event_urgency=event_urgency,
            estimated_cost=estimated_cost,
            market=market,
            q=q,
            context="sports_context",
        )
        post_cost_edge_summary = self.compute_sports_post_cost_edge(
            ticker=ticker,
            family=family,
            calibrated_probability=calibrated_probability_summary.get("calibrated_probability"),
            no_vig_probability=no_vig_summary.get("no_vig_probability"),
            no_vig_odds=no_vig_summary.get("no_vig_odds"),
            dynamic_buffer=dynamic_buffer_summary.get("dynamic_buffer"),
            estimated_cost=estimated_cost,
            spread_bucket="unknown",
            market_lifecycle_state=market_lifecycle_state,
            market=market,
            q=q,
            context="sports_context",
        )
        sports_spread_calibration_bucket = "ultra_tight"
        if spread > AION_SPORTS_MAX_SPREAD_HARD:
            sports_spread_calibration_bucket = "extreme_wide"
        elif spread <= min(0.03, sports_spread_adjusted_threshold * 0.55):
            sports_spread_calibration_bucket = "ultra_tight"
        elif spread <= min(0.06, sports_spread_adjusted_threshold):
            sports_spread_calibration_bucket = "tight"
        elif spread <= min(0.12, max(sports_spread_adjusted_threshold + 0.015, 0.08)):
            sports_spread_calibration_bucket = "medium"
        elif spread <= AION_SPORTS_MAX_SPREAD_SOFT:
            sports_spread_calibration_bucket = "wide_but_possible"
        else:
            sports_spread_calibration_bucket = "extreme_wide"
        sports_spread_bucket = {
            "ultra_tight": "tight",
            "tight": "tight",
            "medium": "acceptable",
            "wide_but_possible": "wide_but_possible",
            "extreme_wide": "unsafe" if spread > AION_SPORTS_MAX_SPREAD_HARD else "too_wide",
        }.get(sports_spread_calibration_bucket, "unknown")
        sports_edge_after_cost = self._clamp(self.to_float(post_cost_edge_summary.get("sports_edge_after_cost"), 0.0), -0.25, 0.25)
        sports_dynamic_buffer = self._clamp(self.to_float(dynamic_buffer_summary.get("dynamic_buffer"), 0.0), 0.0, 0.20)
        spread_info = self._get_sports_adaptive_spread_threshold(
            market,
            spread=spread,
            yes_top_size=yes_top_size,
            no_top_size=no_top_size,
            context=f"sports_calibration:{ticker or family}",
        )
        adaptive_threshold = self.to_float(spread_info.get("adaptive_threshold"), MAX_ENTRY_SPREAD) or MAX_ENTRY_SPREAD
        lifecycle_adjustment = {
            "pregame_far": -0.010,
            "pregame_near": 0.000,
            "live_early": 0.006,
            "live_mid": 0.010,
            "live_late": -0.008,
            "unknown": -0.006,
        }.get(market_lifecycle_state, -0.006)
        depth_bonus = 0.0
        if min_top_size >= 10.0 or max_top_size >= 25.0:
            depth_bonus += 0.015
        elif min_top_size >= 5.0 or max_top_size >= 10.0:
            depth_bonus += 0.007
        if open_interest >= 250.0 or volume >= 100.0:
            depth_bonus += 0.006
        bucket_soft_adjustment = {
            "ultra_tight": 0.010,
            "tight": 0.006,
            "medium": 0.000,
            "wide_but_possible": -0.004,
            "extreme_wide": -0.010,
        }.get(sports_spread_calibration_bucket, 0.0)
        sports_spread_adjusted_threshold = min(
            AION_SPORTS_MAX_SPREAD_SOFT,
            max(0.0, adaptive_threshold + lifecycle_adjustment + depth_bonus + bucket_soft_adjustment - (sports_dynamic_buffer * 0.10)),
        )
        liquidity_strength = self._clamp(
            (min_top_size / max(self.get_market_min_top_of_book_size(market), 1.0)) * 0.35
            + (max_top_size / max(self.get_market_min_top_of_book_size(market), 1.0)) * 0.20
            + self._clamp(open_interest / max(SPORTS_ADAPTIVE_STRONG_OPEN_INTEREST, 1.0)) * 0.25
            + self._clamp(volume / max(MIN_ENTRY_VOLUME, 1.0)) * 0.20
        )
        quote_quality = self._clamp(0.5 + (quote_stability - 0.5) * 1.3)
        regime_support = self._clamp(0.5 + (predictive_regime_score - 0.5) * 1.2)
        momentum_support = self._clamp(0.5 + (momentum_score - 0.18) * 1.8)
        calibrated_probability = self.to_float(calibrated_probability_summary.get("calibrated_probability"), 0.5)
        no_vig_probability = self.to_float(no_vig_summary.get("no_vig_probability"), 0.5)
        no_vig_odds = self.to_float(no_vig_summary.get("no_vig_odds"), 1.0 / max(no_vig_probability, 0.01))
        sports_edge_after_cost = self._clamp(
            self.to_float(post_cost_edge_summary.get("sports_edge_after_cost"), 0.0),
            -0.25,
            0.25,
        )
        sports_dynamic_buffer = self._clamp(self.to_float(dynamic_buffer_summary.get("dynamic_buffer"), sports_dynamic_buffer), 0.0, 0.20)
        quote_ready_from_mapping = bool(yes_bid is not None and yes_ask is not None and no_bid is not None and no_ask is not None)
        quote_ready_reason = (
            "recovered_from_topbook_pair"
            if quote_mapping_applied and quote_ready_from_mapping
            else (
                quote_mapping_block_reason
                or ("incomplete_quote_fields" if not quote_ready_from_mapping else "direct_fields")
            )
        )
        if is_sports and (quote_mapping_applied or quote_mapping_block_reason or not quote_ready_from_mapping or spread is None):
            quote_source_trace = {
                "ticker": ticker or None,
                "family": family,
                "source_quote_fields_present": source_quote_fields_present,
                "source_quote_fields_missing": source_quote_fields_missing,
                "candidate_price_fields_before_mapping": quote_fields_before_mapping,
                "candidate_price_fields_after_mapping": {
                    "yes_bid": yes_bid,
                    "yes_ask": yes_ask,
                    "no_bid": no_bid,
                    "no_ask": no_ask,
                },
                "computed_spread": spread,
                "quote_ready": quote_ready_from_mapping,
                "quote_ready_reason": quote_ready_reason,
                "orderbook_source_object": sports_quote_snapshot,
                "source_of_quote_data": sports_quote_snapshot.get("source_path") or ("topbook_recovery" if quote_mapping_applied else "direct_fields"),
                "yes_top_size": sports_quote_snapshot.get("yes_top_size"),
                "no_top_size": sports_quote_snapshot.get("no_top_size"),
                "yes_top_price": yes_top_price,
                "no_top_price": no_top_price,
            }
            print("[AION-QUOTE-SOURCE-TRACE] " + json.dumps(quote_source_trace, sort_keys=True, default=str))
            print("[AION-PRICE-MAPPING-TRACE] " + json.dumps(
                {
                    **quote_source_trace,
                    "mapping_applied": quote_mapping_applied,
                    "mapping_reason": quote_mapping_reason,
                    "mapping_block_reason": quote_mapping_block_reason,
                },
                sort_keys=True,
                default=str,
            ))
            if quote_ready_from_mapping and quote_mapping_applied:
                print("[AION-QUOTE-MAPPING-RECOVERED] " + json.dumps(
                    {
                        **quote_source_trace,
                        "recovery_source": quote_source_trace.get("source_of_quote_data"),
                        "mapping_reason": quote_mapping_reason,
                    },
                    sort_keys=True,
                    default=str,
                ))
            elif not quote_ready_from_mapping:
                print("[AION-QUOTE-MAPPING-BLOCKED] " + json.dumps(
                    {
                        **quote_source_trace,
                        "block_reason": quote_mapping_block_reason or "incomplete_quote_fields",
                    },
                    sort_keys=True,
                    default=str,
                ))
        explicit_fee_cost = self.to_float(post_cost_edge_summary.get("estimated_cost"), 0.0)
        spread_penalty = 0.0 if sports_spread_bucket == "tight" else (0.01 if sports_spread_bucket == "acceptable" else (0.03 if sports_spread_bucket == "wide_but_possible" else (0.14 if sports_spread_bucket == "too_wide" else 0.22)))
        liquidity_penalty = max(0.0, round((0.45 - liquidity_strength) * 0.02, 4)) if liquidity_strength < 0.45 else 0.0
        volatility_penalty = max(
            0.0,
            round(
                max(0.0, 0.35 - predictive_regime_score) * 0.02
                + max(0.0, abs(momentum_score) - 0.20) * 0.01,
                4,
            ),
        )
        safety_buffer = round(
            self.to_float(dynamic_buffer_summary.get("dynamic_buffer"), 0.0)
            + max(0.0, sports_spread_penalty * 0.0),
            4,
        )
        wide_ok = bool(
            spread <= AION_SPORTS_MAX_SPREAD_SOFT
            and sports_edge_after_cost > 0.0
            and sports_edge_after_cost >= AION_SPORTS_MIN_EDGE_AFTER_COST
            and liquidity_strength >= 0.52
            and quote_quality >= 0.45
            and predictive_regime_score >= 0.35
            and market_lifecycle_state in {"pregame_near", "live_early", "live_mid", "live_late"}
            and (not AION_SPORTS_REQUIRE_DIRECTIONAL_BIAS or directional_bias != "flat" or sports_edge_after_cost >= (AION_SPORTS_MIN_EDGE_AFTER_COST + 0.03))
        )
        very_strong_edge = bool(
            sports_edge_after_cost >= (AION_SPORTS_MIN_EDGE_AFTER_COST + 0.03)
            and liquidity_strength >= 0.58
            and quote_quality >= 0.50
            and predictive_regime_score >= 0.42
        )
        if spread > AION_SPORTS_MAX_SPREAD_HARD:
            sports_spread_bucket = "unsafe"
            sports_spread_calibration_bucket = "extreme_wide"
            sports_spread_penalty = 0.22
            sports_spread_reason = "spread_above_hard_limit"
        elif spread > sports_spread_adjusted_threshold and spread <= AION_SPORTS_MAX_SPREAD_SOFT:
            if wide_ok and (directional_bias != "flat" or very_strong_edge):
                sports_spread_bucket = "wide_but_possible"
                sports_spread_penalty = 0.08
                sports_spread_reason = "wide_but_supported_by_depth_and_edge"
            else:
                sports_spread_bucket = "too_wide"
                if sports_spread_calibration_bucket not in {"ultra_tight", "tight"}:
                    sports_spread_calibration_bucket = "wide_but_possible"
                sports_spread_penalty = 0.16
                sports_spread_reason = "wide_sports_spread_not_supported"
        elif spread > sports_spread_adjusted_threshold:
            sports_spread_bucket = "too_wide"
            sports_spread_penalty = 0.14
            if sports_spread_calibration_bucket not in {"ultra_tight", "tight"}:
                sports_spread_calibration_bucket = "medium"
            sports_spread_reason = "spread_above_adjusted_threshold"
        elif spread <= min(0.06, sports_spread_adjusted_threshold):
            sports_spread_bucket = "tight"
            sports_spread_penalty = 0.0
            if spread <= min(0.03, sports_spread_adjusted_threshold * 0.55):
                sports_spread_calibration_bucket = "ultra_tight"
            elif sports_spread_calibration_bucket == "unknown":
                sports_spread_calibration_bucket = "tight"
            sports_spread_reason = "tight_spread"
        else:
            sports_spread_bucket = "acceptable"
            sports_spread_penalty = 0.03 if spread > 0.10 else 0.01
            if sports_spread_calibration_bucket == "unknown":
                sports_spread_calibration_bucket = "medium"
            sports_spread_reason = "within_adjusted_range"
        if yes_bid is None or yes_ask is None or no_bid is None or no_ask is None:
            sports_spread_bucket = "unsafe"
            sports_spread_calibration_bucket = "extreme_wide"
            sports_spread_penalty = max(sports_spread_penalty, 0.20)
            sports_spread_reason = "missing_quotes"
        if str(directional_bias).strip().lower() == "flat" and spread > 0.10 and sports_edge_after_cost < (AION_SPORTS_MIN_EDGE_AFTER_COST + 0.03):
            sports_spread_bucket = "too_wide"
            sports_spread_penalty = max(sports_spread_penalty, 0.18)
            sports_spread_reason = "flat_bias_with_wide_spread"
        if momentum_score < -0.20 or predictive_regime_score < 0.28 or quote_stability < 0.32:
            sports_spread_penalty = max(sports_spread_penalty, 0.12)
            if sports_spread_bucket in {"tight", "acceptable"}:
                sports_spread_bucket = "too_wide"
                sports_spread_reason = "regime_or_quote_decay"
            if sports_spread_calibration_bucket not in {"ultra_tight", "tight"}:
                sports_spread_calibration_bucket = "extreme_wide" if spread > AION_SPORTS_MAX_SPREAD_SOFT else "wide_but_possible"
        if sports_edge_after_cost <= 0.0:
            sports_candidate_handoff_to_normal_validation = False
            sports_spread_bucket = "unsafe" if spread > AION_SPORTS_MAX_SPREAD_HARD else sports_spread_bucket
            sports_spread_reason = "edge_at_or_below_zero"
        if sports_spread_calibration_bucket == "extreme_wide" and spread <= AION_SPORTS_MAX_SPREAD_SOFT and sports_edge_after_cost > 0.0 and liquidity_strength >= 0.55 and quote_quality >= 0.55 and predictive_regime_score >= 0.45:
            sports_spread_calibration_bucket = "wide_but_possible"
        if sports_edge_after_cost > 0.001 and sports_spread_calibration_bucket in {"ultra_tight", "tight"} and family and str(family).strip().upper().startswith(("KXNBA", "KXMLB", "KXNFL")):
            sports_spread_adjusted_threshold = min(AION_SPORTS_MAX_SPREAD_HARD, sports_spread_adjusted_threshold + 0.004)
            sports_spread_penalty = max(0.0, sports_spread_penalty - 0.006)
            if sports_spread_bucket == "too_wide" and spread <= AION_SPORTS_MAX_SPREAD_SOFT:
                sports_spread_bucket = "acceptable"
                sports_spread_reason = "positive_edge_ultra_tight_relief"
        sports_spread_adjusted_threshold = round(self._clamp(sports_spread_adjusted_threshold, 0.0, AION_SPORTS_MAX_SPREAD_HARD), 4)
        sports_edge_after_cost = round(sports_edge_after_cost, 4)
        sports_spread_penalty = round(self._clamp(sports_spread_penalty, 0.0, 0.30), 4)
        selector_edge_info = self._resolve_aion_selector_edge_value(
            sports_context={
                "final_edge": self.to_float(post_cost_edge_summary.get("final_edge"), sports_edge_after_cost),
                "sports_edge_after_cost_after_family_bias": self.to_float(post_cost_edge_summary.get("sports_edge_after_cost_after_family_bias"), sports_edge_after_cost),
                "sports_edge_after_cost": sports_edge_after_cost,
                "raw_edge_before_cost": self.to_float(post_cost_edge_summary.get("sports_edge_raw"), 0.0),
                "spread_cost": self.to_float(post_cost_edge_summary.get("dynamic_buffer"), 0.0),
                "estimated_cost": self.to_float(post_cost_edge_summary.get("estimated_cost"), 0.0),
            }
        )
        selector_edge_used = self.to_float(selector_edge_info.get("selector_edge_used"), sports_edge_after_cost)
        selector_edge_floor = round(AION_SPORTS_MIN_EDGE_AFTER_COST, 4)
        selector_floor_relief = 0.0
        quote_ready_flag = bool(post_cost_edge_summary.get("quote_ready"))
        final_edge_value = self.to_float(post_cost_edge_summary.get("final_edge"), sports_edge_after_cost)
        duplicate_detail = {"blocked": False, "reason": "not_checked"}
        duplicate_block = False
        unsafe_price_block = bool(sports_spread_bucket == "unsafe" or spread > AION_SPORTS_MAX_SPREAD_HARD or not quote_ready_flag)
        relief_eligible = bool(
            sports_spread_bucket in {"ultra_tight", "tight"}
            and market_lifecycle_state in {"pregame_near", "active_near", "live_early"}
            and selector_edge_used > 0.0
            and final_edge_value > 0.0
            and quote_ready_flag
        )
        relief_block_reason = None
        relief_checks = []
        selector_floor_near = bool(selector_edge_used > 0.0 and selector_edge_used <= (selector_edge_floor + 0.02))
        if selector_floor_near and ticker:
            duplicate_detail = self.check_live_duplicate_position_api(ticker) or {"blocked": False, "reason": "duplicate_check_unavailable"}
            duplicate_block = bool(duplicate_detail.get("blocked"))
            unsafe_price_block = bool(
                unsafe_price_block
                or sports_spread_bucket == "unsafe"
                or spread > AION_SPORTS_MAX_SPREAD_HARD
            )
            relief_eligible = bool(
                relief_eligible
                and not duplicate_block
                and not unsafe_price_block
            )
            relief_checks = [
                ("spread_bucket", sports_spread_bucket in {"ultra_tight", "tight"}),
                ("lifecycle_state", market_lifecycle_state in {"pregame_near", "active_near", "live_early"}),
                ("positive_final_edge", final_edge_value > 0.0),
                ("quote_ready", quote_ready_flag),
                ("no_duplicate", not duplicate_block),
                ("no_unsafe_price", not unsafe_price_block),
            ]
            missing_checks = [name for name, passed in relief_checks if not passed]
            relief_block_reason = ",".join(missing_checks) if missing_checks else None
            relief_check_payload = {
                "ticker": ticker or None,
                "family": family,
                "final_edge": round(final_edge_value, 4),
                "selector_floor": round(selector_edge_floor, 4),
                "effective_floor_after_relief": round(selector_edge_floor, 4),
                "relief_amount": 0.0,
                "spread_bucket": spread_bucket_value,
                "quote_ready": bool(quote_ready_flag),
                "lifecycle_state": market_lifecycle_state_value,
                "duplicate_status": "blocked" if duplicate_block else "clear",
                "unsafe_price_status": "blocked" if unsafe_price_block else "clear",
                "relief_eligible": bool(relief_eligible),
                "relief_block_reason": relief_block_reason,
                "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
            }
            print("[AION-ADAPTIVE-SELECTOR-RELIEF-CHECK] " + json.dumps(relief_check_payload, sort_keys=True, default=str))
        if relief_eligible:
            selector_floor_relief = min(0.010, max(0.0, selector_edge_floor - selector_edge_used))
        selector_floor_effective = round(max(0.005, selector_edge_floor - selector_floor_relief), 4)
        if selector_floor_near and final_edge_value > 0.0:
            relief_status_payload = {
                "ticker": ticker or None,
                "family": family,
                "spread_bucket": spread_bucket_value,
                "market_lifecycle_state": market_lifecycle_state_value,
                "selector_floor_before": round(selector_edge_floor, 4),
                "effective_floor_after_relief": round(selector_floor_effective, 4),
                "relief_amount": round(selector_floor_relief, 4),
                "selector_edge_used": round(selector_edge_used, 4),
                "final_edge": round(final_edge_value, 4),
                "quote_ready": bool(quote_ready_flag),
                "duplicate_status": "blocked" if duplicate_block else "clear",
                "unsafe_price_status": "blocked" if unsafe_price_block else "clear",
                "relief_eligible": bool(relief_eligible),
                "relief_block_reason": relief_block_reason,
                "missing_conditions": [name for name, passed in relief_checks if not passed],
            }
            if selector_floor_relief > 0.0:
                print("[AION-ADAPTIVE-SELECTOR-RELIEF-APPLIED] " + json.dumps(relief_status_payload, sort_keys=True, default=str))
            else:
                print("[AION-ADAPTIVE-SELECTOR-RELIEF-BLOCKED] " + json.dumps(relief_status_payload, sort_keys=True, default=str))
        aggressive_lane_details = self._evaluate_aggressive_positive_edge_lane(
            ticker=ticker,
            family=family,
            final_edge=final_edge_value,
            selector_floor=selector_edge_floor,
            selector_floor_effective=selector_floor_effective,
            quote_ready=quote_ready_flag,
            spread_bucket=spread_bucket_value,
            market_lifecycle_state=market_lifecycle_state_value,
            duplicate_block=duplicate_block,
            unsafe_price_block=unsafe_price_block,
            contracts=AION_AGGRESSIVE_MAX_CONTRACTS,
            trades_today=self.aggressive_trades_today,
            source="selector_floor",
        )
        if selector_floor_near and final_edge_value > 0.0:
            aggressive_lane_payload = {
                "ticker": ticker or None,
                "family": family,
                "final_edge": round(final_edge_value, 4),
                "normal_selector_floor": round(selector_edge_floor, 4),
                "aggressive_edge_floor": round(AION_AGGRESSIVE_EDGE_FLOOR, 4),
                "effective_selector_floor": round(self.to_float(aggressive_lane_details.get("effective_floor_after_aggressive"), selector_floor_effective), 4),
                "relief_amount": round(max(0.0, selector_floor_effective - self.to_float(aggressive_lane_details.get("effective_floor_after_aggressive"), selector_floor_effective)), 4),
                "spread_bucket": spread_bucket_value,
                "quote_ready": bool(quote_ready_flag),
                "lifecycle_state": market_lifecycle_state_value,
                "duplicate_status": aggressive_lane_details.get("duplicate_status"),
                "unsafe_price_status": aggressive_lane_details.get("unsafe_price_status"),
                "contracts": int(aggressive_lane_details.get("contracts") or AION_AGGRESSIVE_MAX_CONTRACTS),
                "trades_today": int(aggressive_lane_details.get("trades_today") or 0),
                "block_reason": aggressive_lane_details.get("block_reason"),
            }
            print("[AION-AGGRESSIVE-LANE-CHECK] " + json.dumps(aggressive_lane_payload, sort_keys=True, default=str))
            if aggressive_lane_details.get("aggressive_lane_approved"):
                print("[AION-AGGRESSIVE-LANE-APPROVED] " + json.dumps(aggressive_lane_payload, sort_keys=True, default=str))
                selector_floor_effective = round(
                    min(
                        selector_floor_effective,
                        self.to_float(aggressive_lane_details.get("effective_floor_after_aggressive"), AION_AGGRESSIVE_EDGE_FLOOR),
                    ),
                    4,
                )
            else:
                print("[AION-AGGRESSIVE-LANE-BLOCKED] " + json.dumps(aggressive_lane_payload, sort_keys=True, default=str))
        cost_buffer_used = round(
            self.to_float(dynamic_buffer_summary.get("dynamic_buffer"), 0.0)
            + explicit_fee_cost,
            4,
        )
        edge_margin_to_floor = round(selector_edge_used - selector_edge_floor, 4)
        edge_margin_to_effective_floor = round(selector_edge_used - selector_floor_effective, 4)
        sports_candidate_handoff_to_normal_validation = bool(
            sports_spread_bucket in {"tight", "acceptable", "wide_but_possible"}
            and selector_edge_used >= selector_floor_effective
            and sports_edge_after_cost > 0.0
            and sports_spread_bucket != "unsafe"
            and quote_quality >= 0.40
            and liquidity_strength >= 0.40
            and predictive_regime_score >= 0.30
            and quote_stability >= 0.30
            and (not AION_SPORTS_REQUIRE_DIRECTIONAL_BIAS or directional_bias != "flat" or selector_edge_used >= (selector_floor_effective + 0.03))
            and (spread <= AION_SPORTS_MAX_SPREAD_SOFT or very_strong_edge)
            and not (predictive_regime_state and str(predictive_regime_state).strip().lower() in {"decaying", "unstable"})
            and not (sports_spread_bucket == "wide_but_possible" and momentum_score < AION_SPORTS_MIN_MOMENTUM_FOR_WIDE)
        )
        if sports_spread_bucket == "wide_but_possible" and directional_bias == "flat" and not very_strong_edge:
            sports_candidate_handoff_to_normal_validation = False
            sports_spread_reason = "wide_spread_flat_bias_requires_exceptional_edge"
        final_sports_action = "reject"
        if sports_spread_bucket == "unsafe":
            final_sports_action = "reject"
        elif sports_candidate_handoff_to_normal_validation:
            final_sports_action = "allow_normal_validation"
        elif sports_spread_bucket == "wide_but_possible" or sports_spread_penalty >= 0.08:
            final_sports_action = "watch"
        elif selector_edge_used >= selector_floor_effective and sports_spread_bucket in {"tight", "acceptable"}:
            final_sports_action = "near_pass"
        reject_reason = None
        if final_sports_action == "reject":
            reject_reason = sports_spread_reason
            if not yes_bid or not yes_ask or not no_bid or not no_ask:
                reject_reason = "missing_quotes"
            elif spread > AION_SPORTS_MAX_SPREAD_HARD:
                reject_reason = "spread_above_hard_limit"
            elif selector_edge_used < selector_floor_effective:
                reject_reason = "edge_below_cost"
            elif selector_edge_used <= 0.0:
                reject_reason = "edge_at_or_below_zero"
            elif AION_SPORTS_REQUIRE_DIRECTIONAL_BIAS and directional_bias == "flat" and spread > 0.10 and selector_edge_used < (selector_floor_effective + 0.03):
                reject_reason = "flat_directional_bias"
            elif predictive_regime_score < 0.28:
                reject_reason = "decaying_regime"
            elif liquidity_strength < 0.40:
                reject_reason = "weak_liquidity"
            if reject_reason == "edge_below_cost":
                selector_floor_payload = {
                    "ticker": ticker or None,
                    "family": family,
                    "raw_edge_before_cost": round(self.to_float(post_cost_edge_summary.get("sports_edge_raw"), 0.0), 4),
                    "sports_edge_after_cost": round(sports_edge_after_cost, 4),
                    "sports_edge_after_cost_after_family_bias": round(self.to_float(post_cost_edge_summary.get("sports_edge_after_cost_after_family_bias"), sports_edge_after_cost), 4),
                    "final_edge": round(self.to_float(post_cost_edge_summary.get("final_edge"), sports_edge_after_cost), 4),
                    "explicit_fee_cost": round(explicit_fee_cost, 4),
                    "spread_penalty": round(spread_penalty, 4),
                    "liquidity_penalty": round(liquidity_penalty, 4),
                    "volatility_penalty": round(volatility_penalty, 4),
                    "safety_buffer": round(safety_buffer, 4),
                    "dynamic_buffer": round(self.to_float(dynamic_buffer_summary.get("dynamic_buffer"), 0.0), 4),
                    "selector_edge_used": round(selector_edge_used, 4),
                    "selector_edge_floor": round(selector_edge_floor, 4),
                    "selector_floor_relief": round(selector_floor_relief, 4),
                    "selector_floor_effective": round(selector_floor_effective, 4),
                    "cost_buffer_used": round(cost_buffer_used, 4),
                    "edge_margin_to_floor": round(edge_margin_to_floor, 4),
                    "edge_margin_to_effective_floor": round(edge_margin_to_effective_floor, 4),
                    "block_reason": reject_reason,
                    "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
                }
                field_consistency_payload = {
                    "ticker": ticker or None,
                    "family": family,
                    "raw_edge_before_cost": selector_floor_payload["raw_edge_before_cost"],
                    "sports_edge_after_cost": selector_floor_payload["sports_edge_after_cost"],
                    "sports_edge_after_cost_after_family_bias": selector_floor_payload["sports_edge_after_cost_after_family_bias"],
                    "final_edge": selector_floor_payload["final_edge"],
                    "selector_edge_used": selector_floor_payload["selector_edge_used"],
                    "execution_gate_edge": selector_floor_payload["final_edge"],
                    "selector_floor_effective": selector_floor_payload["selector_floor_effective"],
                    "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
                    "edge_fields_consistent": bool(
                        abs(selector_floor_payload["sports_edge_after_cost"] - selector_floor_payload["final_edge"]) <= 0.0001
                        and abs(selector_floor_payload["sports_edge_after_cost_after_family_bias"] - selector_floor_payload["final_edge"]) <= 0.0001
                    ),
                }
                blocker_detail_payload = dict(selector_floor_payload)
                blocker_detail_payload.update(
                    {
                        "expectancy": round(max(0.0, selector_edge_used / 0.08), 4),
                        "quote_ready": bool(yes_bid is not None or yes_ask is not None or no_bid is not None or no_ask is not None),
                        "phase55_ready": False,
                        "fastpath_status": "unknown",
                        "cooldown_status": "unknown",
                        "duplicate_status": "unknown",
                        "unsafe_price_status": "unknown",
                        "final_gate_status": "blocked",
                        "final_block_reason": reject_reason,
                        "spread_bucket": spread_bucket_value,
                        "market_lifecycle_state": market_lifecycle_state_value,
                    }
                )
                print("[AION-SELECTOR-MATH] " + json.dumps(selector_floor_payload, sort_keys=True, default=str))
                print("[AION-COST-COMPONENTS] " + json.dumps({
                    "ticker": ticker or None,
                    "family": family,
                    "spread_bucket": spread_bucket_value,
                    "market_lifecycle_state": market_lifecycle_state_value,
                    "explicit_fee_cost": round(explicit_fee_cost, 4),
                    "spread_penalty": round(spread_penalty, 4),
                    "liquidity_penalty": round(liquidity_penalty, 4),
                    "volatility_penalty": round(volatility_penalty, 4),
                    "safety_buffer": round(safety_buffer, 4),
                    "dynamic_buffer": round(self.to_float(dynamic_buffer_summary.get("dynamic_buffer"), 0.0), 4),
                }, sort_keys=True, default=str))
                print("[AION-FLOOR-COMPARISON] " + json.dumps({
                    "ticker": ticker or None,
                    "family": family,
                    "selector_floor": round(selector_edge_floor, 4),
                    "selector_floor_relief": round(selector_floor_relief, 4),
                    "selector_floor_effective": round(selector_floor_effective, 4),
                    "selector_edge_used": round(selector_edge_used, 4),
                    "edge_margin_to_floor": round(edge_margin_to_floor, 4),
                    "edge_margin_to_effective_floor": round(edge_margin_to_effective_floor, 4),
                    "final_block_reason": reject_reason,
                    "quote_ready": bool(yes_bid is not None or yes_ask is not None or no_bid is not None or no_ask is not None),
                }, sort_keys=True, default=str))
                print("[AION-SELECTOR-FLOOR-TRACE] " + json.dumps(selector_floor_payload, sort_keys=True, default=str))
                print("[AION-EDGE-FIELD-CONSISTENCY] " + json.dumps(field_consistency_payload, sort_keys=True, default=str))
                print("[AION-EDGE-BLOCKER-DETAIL] " + json.dumps(blocker_detail_payload, sort_keys=True, default=str))
        calibration_mode = "sports" if is_sports else ("crypto" if family == "KXBTC15M" else "default")
        spread_policy_used = "sports_calibrated" if is_sports else "default"
        threshold_policy_used = "adaptive_final_edge" if is_sports else "default"
        return {
            "ticker": ticker or None,
            "family": family,
            "calibration_mode": calibration_mode,
            "spread_policy_used": spread_policy_used,
            "threshold_policy_used": threshold_policy_used,
            "market_lifecycle_state": market_lifecycle_state,
            "event_urgency": str(event_urgency or market.get("event_urgency") or market.get("urgency") or "unknown"),
            "sports_spread_bucket": sports_spread_bucket,
            "sports_spread_calibration_bucket": sports_spread_calibration_bucket,
            "sports_spread_penalty": sports_spread_penalty,
            "sports_spread_reason": sports_spread_reason,
            "sports_spread_adjusted_threshold": sports_spread_adjusted_threshold,
            "calibrated_probability": round(calibrated_probability, 4),
            "no_vig_probability": round(no_vig_probability, 4),
            "no_vig_odds": round(no_vig_odds, 6),
            "sports_dynamic_buffer": round(sports_dynamic_buffer, 4),
            "sports_edge_after_cost": sports_edge_after_cost,
            "quote_ready": bool(quote_ready_from_mapping),
            "quote_missing": bool(not quote_ready_from_mapping),
            "sports_edge_after_cost_after_family_bias": round(self.to_float(post_cost_edge_summary.get("sports_edge_after_cost_after_family_bias"), sports_edge_after_cost), 4),
            "final_edge": round(self.to_float(post_cost_edge_summary.get("final_edge"), sports_edge_after_cost), 4),
            "aggressive_lane_enabled": bool(AION_AGGRESSIVE_POSITIVE_EDGE_LANE_ENABLED),
            "aggressive_lane_eligible": bool(aggressive_lane_details.get("aggressive_lane_eligible")),
            "aggressive_lane_approved": bool(aggressive_lane_details.get("aggressive_lane_approved")),
            "aggressive_lane_block_reason": aggressive_lane_details.get("aggressive_lane_block_reason"),
            "aggressive_lane_effective_floor": round(self.to_float(aggressive_lane_details.get("effective_floor_after_aggressive"), selector_floor_effective), 4),
            "aggressive_lane_contracts": int(aggressive_lane_details.get("contracts") or AION_AGGRESSIVE_MAX_CONTRACTS),
            "aggressive_lane_trades_today": int(aggressive_lane_details.get("trades_today") or 0),
            "aggressive_lane_cooldown_remaining_seconds": int(aggressive_lane_details.get("cooldown_remaining_seconds") or 0),
            "selector_edge_used": round(selector_edge_used, 4),
            "selector_edge_floor": round(selector_edge_floor, 4),
            "cost_buffer_used": round(cost_buffer_used, 4),
            "edge_margin_to_floor": round(edge_margin_to_floor, 4),
            "source_of_edge_value": selector_edge_info.get("source_of_edge_value"),
            "sports_edge_raw": round(self.to_float(post_cost_edge_summary.get("sports_edge_raw"), 0.0), 4),
            "sports_post_cost_edge": round(self.to_float(post_cost_edge_summary.get("sports_edge_after_cost"), 0.0), 4),
            "estimated_spread_cost": round(estimated_spread_cost, 4),
            "estimated_fee_cost": round(estimated_fee_cost, 4),
            "sports_safety_buffer": round(sports_dynamic_buffer, 4),
            "sports_dynamic_buffer": round(sports_dynamic_buffer, 4),
            "sports_candidate_handoff_to_normal_validation": bool(sports_candidate_handoff_to_normal_validation),
            "final_sports_action": final_sports_action,
            "reject_reason": reject_reason,
            "yes_top_size": round(self.to_float(yes_top_size, 0.0), 4),
            "no_top_size": round(self.to_float(no_top_size, 0.0), 4),
            "open_interest": round(self.to_float(open_interest, 0.0), 4),
            "momentum_score": round(momentum_score, 4),
            "directional_bias": directional_bias,
            "predictive_regime_score": round(predictive_regime_score, 4),
            "quote_stability": round(quote_stability, 4),
            "quote_stability_trend": round(quote_stability_trend, 4),
            "edge_durability_trend": round(edge_durability_trend, 4),
            "family_learning_trend": round(family_learning_trend, 4),
            "edge_score": round(sports_edge_score, 4),
            "liquidity_strength": round(liquidity_strength, 4),
            "liquidity_quality": round(liquidity_quality, 4),
            "regime_support": round(regime_support, 4),
            "momentum_support": round(momentum_support, 4),
            "sports_edge_score_normalized": round(edge_score_norm, 4),
            "adaptive_confidence_modifier": round(adaptive_confidence_modifier, 4),
            "family_rotation_score": round(family_rotation_score, 4),
            "entry_timing_fusion_score": round(entry_timing_fusion_score, 4),
            "queue_state": queue_state,
            "spread": round(spread, 4),
            "yes_bid": round(self.to_float(yes_bid, 0.0), 4) if yes_bid is not None else None,
            "yes_ask": round(self.to_float(yes_ask, 0.0), 4) if yes_ask is not None else None,
            "no_bid": round(self.to_float(no_bid, 0.0), 4) if no_bid is not None else None,
            "no_ask": round(self.to_float(no_ask, 0.0), 4) if no_ask is not None else None,
        }

    def _get_sports_market_calibration_bucket(self, container_name, key):
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "total_sports_scanned": 0,
                "rejected_wide_spread": 0,
                "rejected_edge_below_cost": 0,
                "rejected_flat_bias": 0,
                "rejected_missing_quotes": 0,
                "rejected_weak_liquidity": 0,
                "rejected_decaying_regime": 0,
                "near_pass_count": 0,
                "allow_normal_validation_count": 0,
                "best_sports_edge_after_cost": 0.0,
                "best_sports_score": 0.0,
                "best_sports_ticker": None,
                "best_sports_family": None,
                "best_sports_reason": "unknown",
                "latest_sports_action": "reject",
                "latest_reject_reason": "unknown",
                "latest_summary": {},
                "score_history": deque(maxlen=24),
                "action_history": deque(maxlen=24),
                "blocker_history": deque(maxlen=24),
            },
        )
        bucket.setdefault("score_history", deque(maxlen=24))
        bucket.setdefault("action_history", deque(maxlen=24))
        bucket.setdefault("blocker_history", deque(maxlen=24))
        return bucket

    def _build_sports_market_calibration_family_summary(self, family=None):
        family = str(family or "UNKNOWN").strip().upper() or "UNKNOWN"
        ticker_container = getattr(self, "sports_harvest_by_ticker", {}) or {}
        family_buckets = []
        if isinstance(ticker_container, dict):
            for bucket in ticker_container.values():
                if not isinstance(bucket, dict):
                    continue
                if str(bucket.get("family") or "").strip().upper() == family:
                    family_buckets.append(bucket)
        family_bucket = self._get_sports_market_calibration_bucket("sports_harvest_by_family", f"family:{family}")
        if not family_buckets:
            summary = {
                "family": family,
                "candidate_count": 0,
                "total_sports_scanned": 0,
                "rejected_wide_spread": 0,
                "rejected_edge_below_cost": 0,
                "rejected_flat_bias": 0,
                "rejected_missing_quotes": 0,
                "rejected_weak_liquidity": 0,
                "rejected_decaying_regime": 0,
                "near_pass_count": 0,
                "allow_normal_validation_count": 0,
                "clv_improving_count": 0,
                "clv_decaying_count": 0,
                "clv_recovered_after_near_pass_count": 0,
                "best_sports_ticker": None,
                "best_sports_calibrated_probability": 0.0,
                "best_sports_no_vig_probability": 0.0,
                "best_sports_edge_after_cost": 0.0,
                "best_sports_family": None,
                "best_sports_score": 0.0,
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
            family_bucket["last_summary"] = summary
            return summary
        best_bucket = max(
            family_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("best_sports_edge_after_cost"), 0.0),
                self.to_float(bucket.get("best_sports_score"), 0.0),
            ),
        )
        summary = {
            "family": family,
            "candidate_count": int(len(family_buckets)),
            "total_sports_scanned": int(sum(int(bucket.get("total_sports_scanned", 0) or 0) for bucket in family_buckets)),
            "rejected_wide_spread": int(sum(int(bucket.get("rejected_wide_spread", 0) or 0) for bucket in family_buckets)),
            "rejected_edge_below_cost": int(sum(int(bucket.get("rejected_edge_below_cost", 0) or 0) for bucket in family_buckets)),
            "rejected_flat_bias": int(sum(int(bucket.get("rejected_flat_bias", 0) or 0) for bucket in family_buckets)),
            "rejected_missing_quotes": int(sum(int(bucket.get("rejected_missing_quotes", 0) or 0) for bucket in family_buckets)),
            "rejected_weak_liquidity": int(sum(int(bucket.get("rejected_weak_liquidity", 0) or 0) for bucket in family_buckets)),
            "rejected_decaying_regime": int(sum(int(bucket.get("rejected_decaying_regime", 0) or 0) for bucket in family_buckets)),
            "near_pass_count": int(sum(int(bucket.get("near_pass_count", 0) or 0) for bucket in family_buckets)),
            "allow_normal_validation_count": int(sum(int(bucket.get("allow_normal_validation_count", 0) or 0) for bucket in family_buckets)),
            "clv_improving_count": int(sum(int(bucket.get("clv_improving_count", 0) or 0) for bucket in family_buckets)),
            "clv_decaying_count": int(sum(int(bucket.get("clv_decaying_count", 0) or 0) for bucket in family_buckets)),
            "clv_recovered_after_near_pass_count": int(sum(int(bucket.get("clv_recovered_after_near_pass_count", 0) or 0) for bucket in family_buckets)),
            "best_sports_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_sports_family": str(best_bucket.get("family") or "").strip().upper() or None,
            "best_sports_calibrated_probability": round(self.to_float(best_bucket.get("calibrated_probability"), 0.0) or 0.0, 4),
            "best_sports_no_vig_probability": round(self.to_float(best_bucket.get("no_vig_probability"), 0.0) or 0.0, 4),
            "best_sports_edge_after_cost": round(self.to_float(best_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, 4),
            "best_sports_score": round(self.to_float(best_bucket.get("best_sports_score"), 0.0) or 0.0, 4),
            "best_sports_reason": str(best_bucket.get("best_sports_reason") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }
        family_bucket["last_summary"] = summary
        return summary

    def _build_sports_market_calibration_overall_summary(self):
        ticker_container = getattr(self, "sports_harvest_by_ticker", {}) or {}
        family_container = getattr(self, "sports_harvest_by_family", {}) or {}
        ticker_buckets = [bucket for bucket in ticker_container.values() if isinstance(bucket, dict)]
        family_buckets = [bucket for bucket in family_container.values() if isinstance(bucket, dict)]
        if not ticker_buckets:
            return {
                "scope": "overall",
                "total_sports_scanned": 0,
                "rejected_wide_spread": 0,
                "rejected_edge_below_cost": 0,
                "rejected_flat_bias": 0,
                "rejected_missing_quotes": 0,
                "rejected_weak_liquidity": 0,
                "rejected_decaying_regime": 0,
                "near_pass_count": 0,
                "allow_normal_validation_count": 0,
                "clv_improving_count": 0,
                "clv_decaying_count": 0,
                "clv_recovered_after_near_pass_count": 0,
                "best_sports_ticker": None,
                "best_sports_family": None,
                "best_sports_calibrated_probability": 0.0,
                "best_sports_no_vig_probability": 0.0,
                "best_sports_edge_after_cost": 0.0,
                "best_sports_score": 0.0,
                "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
            }
        best_bucket = max(
            ticker_buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("best_sports_edge_after_cost"), 0.0),
                self.to_float(bucket.get("best_sports_score"), 0.0),
            ),
        )
        return {
            "scope": "overall",
            "total_sports_scanned": int(sum(int(bucket.get("total_sports_scanned", 0) or 0) for bucket in ticker_buckets)),
            "rejected_wide_spread": int(sum(int(bucket.get("rejected_wide_spread", 0) or 0) for bucket in ticker_buckets)),
            "rejected_edge_below_cost": int(sum(int(bucket.get("rejected_edge_below_cost", 0) or 0) for bucket in ticker_buckets)),
            "rejected_flat_bias": int(sum(int(bucket.get("rejected_flat_bias", 0) or 0) for bucket in ticker_buckets)),
            "rejected_missing_quotes": int(sum(int(bucket.get("rejected_missing_quotes", 0) or 0) for bucket in ticker_buckets)),
            "rejected_weak_liquidity": int(sum(int(bucket.get("rejected_weak_liquidity", 0) or 0) for bucket in ticker_buckets)),
            "rejected_decaying_regime": int(sum(int(bucket.get("rejected_decaying_regime", 0) or 0) for bucket in ticker_buckets)),
            "near_pass_count": int(sum(int(bucket.get("near_pass_count", 0) or 0) for bucket in ticker_buckets)),
            "allow_normal_validation_count": int(sum(int(bucket.get("allow_normal_validation_count", 0) or 0) for bucket in ticker_buckets)),
            "clv_improving_count": int(sum(int(bucket.get("clv_improving_count", 0) or 0) for bucket in ticker_buckets)),
            "clv_decaying_count": int(sum(int(bucket.get("clv_decaying_count", 0) or 0) for bucket in ticker_buckets)),
            "clv_recovered_after_near_pass_count": int(sum(int(bucket.get("clv_recovered_after_near_pass_count", 0) or 0) for bucket in ticker_buckets)),
            "best_sports_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_sports_family": str(best_bucket.get("family") or "").strip().upper() or None,
            "best_sports_calibrated_probability": round(self.to_float(best_bucket.get("calibrated_probability"), 0.0) or 0.0, 4),
            "best_sports_no_vig_probability": round(self.to_float(best_bucket.get("no_vig_probability"), 0.0) or 0.0, 4),
            "best_sports_edge_after_cost": round(self.to_float(best_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, 4),
            "best_sports_score": round(self.to_float(best_bucket.get("best_sports_score"), 0.0) or 0.0, 4),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_sports_market_calibration_telemetry(self, *, ticker_bucket=None, family_bucket=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(ticker_bucket.get("family") or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        if not summary:
            summary = {
                "ticker": ticker or "unknown",
                "family": family,
                "sports_spread_bucket": str(ticker_bucket.get("latest_sports_spread_bucket") or "unknown"),
                "sports_spread_adjusted_threshold": round(self.to_float(ticker_bucket.get("latest_sports_spread_adjusted_threshold"), 0.0) or 0.0, 4),
                "sports_edge_after_cost": round(self.to_float(ticker_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, 4),
                "final_sports_action": str(ticker_bucket.get("latest_sports_action") or "reject"),
                "reject_reason": str(ticker_bucket.get("latest_reject_reason") or "unknown"),
            }
        emit_key = ticker or family
        last_emit = float(getattr(self, "sports_harvest_last_signal_ts_by_key", {}).get(emit_key, 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 90.0:
            return None
        if ticker:
            self.sports_harvest_last_signal_ts_by_key[ticker] = now
        if family:
            self.sports_harvest_last_signal_ts_by_key[family] = now
        print("[LIVE-SPORTS-PROBABILITY] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "calibrated_probability": summary.get("calibrated_probability"),
            "base_probability": summary.get("no_vig_probability"),
            "context": summary.get("calibration_mode"),
            "directional_bias": summary.get("directional_bias"),
            "momentum_score": summary.get("momentum_score"),
            "directional_consistency": summary.get("directional_consistency"),
            "orderbook_pressure": summary.get("orderbook_pressure"),
            "predictive_regime_score": summary.get("predictive_regime_score"),
            "quote_stability_trend": summary.get("quote_stability_trend"),
        }, sort_keys=True, default=str))
        print("[LIVE-SPORTS-NO-VIG] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "no_vig_probability": summary.get("no_vig_probability"),
            "no_vig_odds": summary.get("no_vig_odds"),
            "confidence": summary.get("no_vig_confidence") or summary.get("no_vig_probability"),
            "spread": summary.get("spread"),
            "liquidity_quality": summary.get("liquidity_quality"),
            "market_lifecycle_state": summary.get("market_lifecycle_state"),
            "event_urgency": summary.get("event_urgency"),
        }, sort_keys=True, default=str))
        print("[LIVE-SPORTS-DYNAMIC-BUFFER] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "dynamic_buffer": summary.get("sports_dynamic_buffer"),
            "spread_bucket": summary.get("sports_spread_calibration_bucket") or summary.get("sports_spread_bucket"),
            "instability_penalty": summary.get("sports_dynamic_buffer"),
            "stability_credit": summary.get("sports_score"),
            "bucket_multiplier": summary.get("sports_spread_calibration_bucket"),
            "market_lifecycle_state": summary.get("market_lifecycle_state"),
        }, sort_keys=True, default=str))
        print("[LIVE-SPORTS-POST-COST-EDGE] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "sports_edge_raw": summary.get("sports_edge_raw"),
            "sports_edge_after_cost": summary.get("sports_edge_after_cost"),
            "dynamic_buffer": summary.get("sports_dynamic_buffer"),
            "calibrated_probability": summary.get("calibrated_probability"),
            "no_vig_probability": summary.get("no_vig_probability"),
            "no_vig_odds": summary.get("no_vig_odds"),
            "spread_bucket": summary.get("sports_spread_calibration_bucket") or summary.get("sports_spread_bucket"),
        }, sort_keys=True, default=str))
        print("[LIVE-SPORTS-HARVEST-DIAGNOSTIC] " + json.dumps(summary, sort_keys=True, default=str))
        if summary.get("sports_candidate_handoff_to_normal_validation"):
            print("[LIVE-SPORTS-NORMAL-VALIDATION-HANDOFF] " + json.dumps({
                "ticker": summary.get("ticker"),
                "family": summary.get("family"),
                "sports_edge_after_cost": summary.get("sports_edge_after_cost"),
                "sports_spread_bucket": summary.get("sports_spread_bucket"),
                "market_lifecycle_state": summary.get("market_lifecycle_state"),
                "final_sports_action": summary.get("final_sports_action"),
            }, sort_keys=True, default=str))
        self.last_sports_harvest_summary = dict(summary)
        self.last_sports_harvest_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_sports_harvest_overall_summary = self._build_sports_market_calibration_overall_summary()
        print("[LIVE-SPORTS-CLV-TRACK] " + json.dumps({
            "ticker": summary.get("ticker"),
            "family": summary.get("family"),
            "clv_improving_count": summary.get("clv_improving_count"),
            "clv_decaying_count": summary.get("clv_decaying_count"),
            "clv_recovered_after_near_pass_count": summary.get("clv_recovered_after_near_pass_count"),
            "sports_edge_after_cost": summary.get("sports_edge_after_cost"),
            "spread": summary.get("spread"),
        }, sort_keys=True, default=str))
        print("[LIVE-SPORTS-CALIBRATION-DASHBOARD] " + json.dumps({
            "candidate_count": self.last_sports_harvest_overall_summary.get("total_sports_scanned", 0),
            "strongest_sports_ticker": self.last_sports_harvest_overall_summary.get("best_sports_ticker"),
            "strongest_sports_family": self.last_sports_harvest_overall_summary.get("best_sports_family"),
            "calibrated_probability": summary.get("calibrated_probability"),
            "no_vig_probability": summary.get("no_vig_probability"),
            "sports_edge_after_cost": summary.get("sports_edge_after_cost"),
            "dynamic_buffer": summary.get("sports_dynamic_buffer"),
            "sports_spread_bucket": summary.get("sports_spread_calibration_bucket") or summary.get("sports_spread_bucket"),
            "clv_improving_count": self.last_sports_harvest_overall_summary.get("clv_improving_count", 0),
            "clv_decaying_count": self.last_sports_harvest_overall_summary.get("clv_decaying_count", 0),
            "near_pass_count": self.last_sports_harvest_overall_summary.get("near_pass_count", 0),
            "allow_normal_validation_count": self.last_sports_harvest_overall_summary.get("allow_normal_validation_count", 0),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }, sort_keys=True, default=str))
        print("[LIVE-SPORTS-BLOCKER-SUMMARY] " + json.dumps(self.last_sports_harvest_overall_summary, sort_keys=True, default=str))
        print("[LIVE-MARKET-FAMILY-CALIBRATION] " + json.dumps({
            "family": family,
            "calibration_mode": summary.get("calibration_mode") or ("sports" if self.is_sports_family(family, ticker=ticker) else ("crypto" if family == "KXBTC15M" else "default")),
            "spread_policy_used": summary.get("spread_policy_used") or "default",
            "threshold_policy_used": summary.get("threshold_policy_used") or "default",
        }, sort_keys=True, default=str))
        return summary

    def _get_sports_harvest_watchlist_bucket(self, container_name, key):
        if sports_harvest is not None and hasattr(sports_harvest, "get_or_create_bucket"):
            container = getattr(self, container_name, None)
            if not isinstance(container, dict):
                container = {}
                setattr(self, container_name, container)
            defaults = {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "scan_count": 0,
                "near_harvest_count": 0,
                "improving_count": 0,
                "best_edge_after_cost": -1.0,
                "best_score": 0.0,
                "best_spread_bucket": "unknown",
                "latest_edge_after_cost": 0.0,
                "latest_score": 0.0,
                "latest_spread_bucket": "unknown",
                "latest_reason": "unknown",
                "latest_state": "blocked",
                "last_summary": {},
            }
            bucket = sports_harvest.get_or_create_bucket(container, key, defaults=defaults)
            return bucket
        buckets = getattr(self, container_name, None)
        if not isinstance(buckets, dict):
            buckets = {}
            setattr(self, container_name, buckets)
        bucket = buckets.setdefault(
            key,
            {
                "first_seen_time": None,
                "last_seen_time": 0.0,
                "ticker": None,
                "family": None,
                "scan_count": 0,
                "near_harvest_count": 0,
                "improving_count": 0,
                "best_edge_after_cost": -1.0,
                "best_score": 0.0,
                "best_spread_bucket": "unknown",
                "latest_edge_after_cost": 0.0,
                "latest_score": 0.0,
                "latest_spread_bucket": "unknown",
                "latest_reason": "unknown",
                "latest_state": "blocked",
                "last_summary": {},
            },
        )
        return bucket

    def _build_sports_harvest_dashboard_summary(self):
        if sports_harvest is not None and hasattr(sports_harvest, "build_harvest_dashboard_summary"):
            try:
                return sports_harvest.build_harvest_dashboard_summary(
                    getattr(self, "sports_harvest_watchlist_by_ticker", {}) or {},
                    live_arb_enabled=bool(AION_LIVE_ARB_ENABLED),
                )
            except Exception:
                pass
        watchlist = getattr(self, "sports_harvest_watchlist_by_ticker", {}) or {}
        buckets = [bucket for bucket in watchlist.values() if isinstance(bucket, dict)]
        if not buckets:
            return {
                "watchlist_count": 0,
                "improving_count": 0,
                "near_harvest_count": 0,
                "best_ticker": None,
                "best_family": None,
                "best_edge_after_cost": 0.0,
                "best_score": 0.0,
                "best_spread_bucket": None,
                "live_arb_enabled": False,
            }
        best_bucket = max(
            buckets,
            key=lambda bucket: (
                self.to_float(bucket.get("best_edge_after_cost"), -1.0),
                self.to_float(bucket.get("best_score"), 0.0),
            ),
        )
        return {
            "watchlist_count": int(len(buckets)),
            "improving_count": int(sum(int(bucket.get("improving_count", 0) or 0) for bucket in buckets)),
            "near_harvest_count": int(sum(int(bucket.get("near_harvest_count", 0) or 0) for bucket in buckets)),
            "best_ticker": str(best_bucket.get("ticker") or "").strip() or None,
            "best_family": str(best_bucket.get("family") or "").strip().upper() or None,
            "best_edge_after_cost": round(self.to_float(best_bucket.get("best_edge_after_cost"), 0.0) or 0.0, 4),
            "best_score": round(self.to_float(best_bucket.get("best_score"), 0.0) or 0.0, 4),
            "best_spread_bucket": str(best_bucket.get("best_spread_bucket") or "unknown"),
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_sports_harvest_activation_telemetry(self, *, ticker_bucket=None, family_bucket=None, summary=None, force=False):
        ticker_bucket = ticker_bucket if isinstance(ticker_bucket, dict) else {}
        family_bucket = family_bucket if isinstance(family_bucket, dict) else {}
        summary = summary if isinstance(summary, dict) else self._build_sports_harvest_dashboard_summary()
        ticker = str(ticker_bucket.get("ticker") or "").strip()
        family = str(ticker_bucket.get("family") or family_bucket.get("family") or "").strip().upper() or "UNKNOWN"
        now = time.time()
        emit_key = ticker or family
        last_emit = float(getattr(self, "sports_harvest_last_signal_ts_by_key", {}).get(f"activation:{emit_key}", 0.0) or 0.0)
        if not force and ticker and (now - last_emit) < 75.0:
            return summary
        if ticker:
            self.sports_harvest_last_signal_ts_by_key[f"activation:{ticker}"] = now
        if family:
            self.sports_harvest_last_signal_ts_by_key[f"activation:{family}"] = now
        dashboard_last_emit = float(getattr(self, "last_sports_harvest_dashboard_ts", 0.0) or 0.0)
        if force or (now - dashboard_last_emit) >= 45.0:
            self.last_sports_harvest_dashboard_ts = now
            print("[LIVE-SPORTS-HARVEST-DASHBOARD] " + json.dumps(summary, sort_keys=True, default=str))
        return summary

    def _build_aion_infra_dashboard_summary(self):
        runtime_layout = getattr(self, "runtime_layout", {}) or {}
        persistent_engine = getattr(self, "aion_persistent_intelligence", None)
        ticker_profiles = getattr(persistent_engine, "ticker_profiles", {}) if persistent_engine is not None else {}
        family_profiles = getattr(persistent_engine, "family_profiles", {}) if persistent_engine is not None else {}
        watchlist = getattr(self, "sports_harvest_watchlist_by_ticker", {}) or {}
        cache_dir = runtime_layout.get("cache") if isinstance(runtime_layout, dict) else None
        cache_entries = 0
        if cache_dir and os.path.isdir(cache_dir):
            try:
                cache_entries = len([name for name in os.listdir(cache_dir) if not name.startswith(".")])
            except Exception:
                cache_entries = 0
        memory_files = {}
        for path in (
            runtime_memory_file("aion_persistent_intelligence.json") if callable(runtime_memory_file) else None,
            runtime_memory_file("aion_persistent_intelligence.json.tmp") if callable(runtime_memory_file) else None,
        ):
            if path and os.path.exists(path):
                try:
                    memory_files[os.path.basename(path)] = os.path.getsize(path)
                except Exception:
                    pass
        active_families = {
            str(bucket.get("family") or "").strip().upper()
            for bucket in list((ticker_profiles or {}).values()) + list((family_profiles or {}).values()) + list((watchlist or {}).values())
            if isinstance(bucket, dict) and str(bucket.get("family") or "").strip()
        }
        module_count = int(self.aion_module_count or 0)
        runtime_memory_objects = int(len([bucket for bucket in ticker_profiles.values() if isinstance(bucket, dict)])) + int(
            len([bucket for bucket in family_profiles.values() if isinstance(bucket, dict)])
        )
        runtime_memory_objects += int(len([bucket for bucket in watchlist.values() if isinstance(bucket, dict)]))
        runtime_health = "ok"
        if persistent_engine is None:
            runtime_health = "degraded"
        if not runtime_layout:
            runtime_health = "degraded"
        return {
            "module_count": module_count,
            "runtime_memory_objects": runtime_memory_objects,
            "watchlist_count": int(len([bucket for bucket in watchlist.values() if isinstance(bucket, dict)])),
            "persistent_profiles_count": int(len([bucket for bucket in ticker_profiles.values() if isinstance(bucket, dict)])) + int(
                len([bucket for bucket in family_profiles.values() if isinstance(bucket, dict)])
            ),
            "cache_entries": int(cache_entries),
            "active_families": int(len(active_families)),
            "memory_file_sizes": memory_files,
            "runtime_health": runtime_health,
            "live_arb_enabled": bool(AION_LIVE_ARB_ENABLED),
        }

    def _emit_aion_infra_dashboard(self, *, force=False):
        now = time.time()
        last_emit = float(getattr(self, "last_aion_infra_dashboard_ts", 0.0) or 0.0)
        if not force and (now - last_emit) < 120.0:
            return getattr(self, "last_aion_infra_dashboard_summary", {}) or self._build_aion_infra_dashboard_summary()
        summary = self._build_aion_infra_dashboard_summary()
        self.last_aion_infra_dashboard_ts = now
        self.last_aion_infra_dashboard_summary = dict(summary)
        print("[AION-INFRA-DASHBOARD] " + json.dumps(summary, sort_keys=True, default=str))
        return summary

    def _update_aion_persistent_intelligence(
        self,
        *,
        ticker=None,
        family=None,
        market=None,
        q=None,
        predictive_regime_summary=None,
        family_learning_summary=None,
        microstructure_summary=None,
        safe_queue_summary=None,
        entry_timing_observation=None,
        sports_harvest_summary=None,
        sports_context=None,
        selected_quote=None,
        candidates=None,
        source="live_cycle",
    ):
        engine = getattr(self, "aion_persistent_intelligence", None)
        if engine is None:
            return None
        market = market if isinstance(market, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        safe_queue_summary = safe_queue_summary if isinstance(safe_queue_summary, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        sports_harvest_summary = sports_harvest_summary if isinstance(sports_harvest_summary, dict) else {}
        sports_context = sports_context if isinstance(sports_context, dict) else {}
        selected_quote = selected_quote if selected_quote is not None else (candidates[0][1] if candidates else None)
        selected_ticker = str(ticker or getattr(selected_quote, "ticker", "") or market.get("ticker") or "").strip()
        if not selected_ticker:
            return None
        family = str(family or getattr(selected_quote, "family", "") or self.get_market_family(market) or "").strip().upper() or "UNKNOWN"
        market_type = "sports" if self.is_sports_family(family, ticker=selected_ticker) else "default"
        spread_quality = self.to_float(
            microstructure_summary.get("spread_stability"),
            0.5 if str(sports_harvest_summary.get("sports_spread_bucket") or "").strip().lower() in {"ultra_tight", "tight"} else 0.0,
        )
        quote_stability = self.to_float(microstructure_summary.get("quote_stability"), self.to_float(sports_context.get("quote_stability_trend"), 0.5))
        directional_consistency = self.to_float(microstructure_summary.get("directional_consistency"), self.to_float(sports_context.get("directional_consistency"), 0.5))
        stability_score = max(
            0.0,
            min(
                1.0,
                (
                    self.to_float(microstructure_summary.get("quote_stability"), 0.5)
                    + self.to_float(microstructure_summary.get("spread_stability"), 0.5)
                    + self.to_float(entry_timing_observation.get("timing_stability"), 0.5)
                )
                / 3.0,
            ),
        )
        near_pass = bool(
            sports_harvest_summary.get("near_harvest_count")
            or safe_queue_summary.get("near_ready_count")
            or str(entry_timing_observation.get("phase55_status") or "").strip().lower() == "entry_ready"
        )
        improving_edge = bool(
            self.to_float(sports_context.get("sports_edge_after_cost"), 0.0) > 0.0
            or self.to_float(predictive_regime_summary.get("predictive_regime_score"), 0.0) > 0.6
            or self.to_float(family_learning_summary.get("family_learning_score"), 0.0) > 0.55
        )
        decaying_edge = bool(
            self.to_float(sports_context.get("sports_edge_after_cost"), 0.0) < 0.0
            and self.to_float(sports_context.get("sports_dynamic_buffer"), 0.0) > 0.01
            and self.to_float(predictive_regime_summary.get("predictive_regime_score"), 0.0) < 0.45
        )
        observation = {
            "ticker": selected_ticker,
            "family": family,
            "spread_quality": spread_quality,
            "stability_score": stability_score,
            "near_pass": near_pass,
            "improving_edge": improving_edge,
            "decaying_edge": decaying_edge,
            "quote_stability": quote_stability,
            "directional_consistency": directional_consistency,
            "volatility_regime": self.to_float(predictive_regime_summary.get("regime_decay_score"), 0.5),
            "execution_outcome": str((self.last_live_select_summary or {}).get("final_no_candidate_reason") or (self.last_live_select_summary or {}).get("execution_block_reason") or "unknown"),
            "outcome_strength": self.to_float(sports_context.get("sports_edge_after_cost"), 0.0),
            "blocker_reason": str((self.last_live_select_summary or {}).get("top_reject_reason") or (self.last_live_select_summary or {}).get("execution_block_reason") or "unknown"),
            "timestamp": time.time(),
        }
        ticker_summary = engine.record_ticker_behavior(selected_ticker, family, market_type=market_type, **observation)
        family_summary = engine.record_family_profile(family, market_type=market_type, ticker=selected_ticker, **observation)
        self.last_aion_ticker_behavior_summary = dict(ticker_summary or {})
        self.last_aion_family_profile_summary = dict(family_summary or {})
        overall_summary = engine.maybe_emit_summary(force=False)
        self.last_aion_intelligence_summary = dict(overall_summary or {})
        self._emit_aion_infra_dashboard(force=False)
        return {
            "ticker_summary": ticker_summary,
            "family_summary": family_summary,
            "overall_summary": overall_summary,
        }

    def _update_sports_market_calibration(self, *, ticker=None, family=None, market=None, q=None, predictive_regime_summary=None, adaptive_confidence_summary=None, family_rotation_summary=None, microstructure_summary=None, learning_summary=None, family_learning_summary=None, entry_timing_observation=None, sports_momentum=None, sports_edge=None, sports_context=None, force=False):
        ticker = str(ticker or getattr(q, "ticker", "") or "").strip()
        if not ticker:
            return None
        family = str(family or getattr(q, "family", "") or "").strip().upper() or "UNKNOWN"
        market = market if isinstance(market, dict) else {}
        predictive_regime_summary = predictive_regime_summary if isinstance(predictive_regime_summary, dict) else {}
        adaptive_confidence_summary = adaptive_confidence_summary if isinstance(adaptive_confidence_summary, dict) else {}
        family_rotation_summary = family_rotation_summary if isinstance(family_rotation_summary, dict) else {}
        microstructure_summary = microstructure_summary if isinstance(microstructure_summary, dict) else {}
        learning_summary = learning_summary if isinstance(learning_summary, dict) else {}
        family_learning_summary = family_learning_summary if isinstance(family_learning_summary, dict) else {}
        entry_timing_observation = entry_timing_observation if isinstance(entry_timing_observation, dict) else {}
        sports_momentum = sports_momentum if isinstance(sports_momentum, dict) else {}
        sports_edge = sports_edge if isinstance(sports_edge, dict) else {}
        sports_context = sports_context if isinstance(sports_context, dict) else {}
        ticker_bucket = self._get_sports_market_calibration_bucket("sports_harvest_by_ticker", f"ticker:{ticker}")
        family_bucket = self._get_sports_market_calibration_bucket("sports_harvest_by_family", f"family:{family}")
        previous_summary = ticker_bucket.get("last_summary") if isinstance(ticker_bucket.get("last_summary"), dict) else {}
        now = time.time()
        ticker_bucket["first_seen_time"] = ticker_bucket.get("first_seen_time") or now
        ticker_bucket["last_seen_time"] = now
        ticker_bucket["ticker"] = ticker
        ticker_bucket["family"] = family
        family_bucket["first_seen_time"] = family_bucket.get("first_seen_time") or now
        family_bucket["last_seen_time"] = now
        family_bucket["ticker"] = ticker
        family_bucket["family"] = family
        ticker_bucket["total_sports_scanned"] = int(ticker_bucket.get("total_sports_scanned", 0) or 0) + 1
        family_bucket["total_sports_scanned"] = int(family_bucket.get("total_sports_scanned", 0) or 0) + 1
        spread_bucket = str(sports_context.get("sports_spread_bucket") or "unknown").strip().lower()
        calibration_bucket = str(sports_context.get("sports_spread_calibration_bucket") or spread_bucket or "unknown").strip().lower()
        action = str(sports_context.get("final_sports_action") or "reject").strip().lower()
        reject_reason = str(sports_context.get("reject_reason") or "unknown").strip().lower()
        sports_edge_after_cost = self.to_float(sports_context.get("sports_edge_after_cost"), 0.0)
        calibrated_probability = self.to_float(sports_context.get("calibrated_probability"), 0.5)
        no_vig_probability = self.to_float(sports_context.get("no_vig_probability"), 0.5)
        no_vig_odds = self.to_float(sports_context.get("no_vig_odds"), 1.0 / max(no_vig_probability, 0.01))
        sports_dynamic_buffer = self.to_float(sports_context.get("sports_dynamic_buffer"), 0.01)
        sports_score = self._clamp(
            self.to_float(sports_context.get("sports_edge_score_normalized"), 0.0) * 0.28
            + self.to_float(sports_context.get("predictive_regime_score"), 0.0) * 0.18
            + self.to_float(sports_context.get("quote_stability"), 0.0) * 0.14
            + self.to_float(sports_context.get("liquidity_strength"), 0.0) * 0.14
            + self.to_float(sports_context.get("momentum_score"), 0.0) * 0.10
            + self.to_float(sports_context.get("sports_spread_penalty"), 0.0) * -0.12
            + self.to_float(family_rotation_summary.get("family_rotation_score"), 0.0) * 0.08
            + self.to_float(adaptive_confidence_summary.get("adaptive_confidence_modifier"), 0.0) * 0.06
            + self.to_float(entry_timing_observation.get("entry_timing_fusion_score"), 0.0) * 0.08
            + self.to_float(learning_summary.get("family_learning_score"), 0.0) * 0.04
        )
        ticker_bucket["best_sports_score"] = max(self.to_float(ticker_bucket.get("best_sports_score"), 0.0) or 0.0, sports_score)
        ticker_bucket["best_sports_edge_after_cost"] = max(self.to_float(ticker_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, sports_edge_after_cost)
        ticker_bucket["best_sports_ticker"] = ticker
        ticker_bucket["best_sports_family"] = family
        ticker_bucket["latest_sports_spread_bucket"] = spread_bucket
        ticker_bucket["latest_sports_spread_calibration_bucket"] = calibration_bucket
        ticker_bucket["latest_sports_spread_adjusted_threshold"] = self.to_float(sports_context.get("sports_spread_adjusted_threshold"), 0.0)
        ticker_bucket["latest_sports_action"] = action
        ticker_bucket["latest_reject_reason"] = reject_reason
        prev_edge_after_cost = self.to_float(previous_summary.get("sports_edge_after_cost"), 0.0)
        prev_spread = self.to_float(previous_summary.get("spread"), 0.0)
        prev_action = str(previous_summary.get("final_sports_action") or "reject").strip().lower()
        edge_improved = bool(sports_edge_after_cost > prev_edge_after_cost + 0.003)
        spread_tightened = bool(prev_spread > 0.0 and self.to_float(sports_context.get("spread"), 0.0) < prev_spread - 0.001)
        favorable_after_near_pass = bool(prev_action == "near_pass" and sports_edge_after_cost > prev_edge_after_cost)
        if edge_improved:
            ticker_bucket["clv_improving_count"] = int(ticker_bucket.get("clv_improving_count", 0) or 0) + 1
            family_bucket["clv_improving_count"] = int(family_bucket.get("clv_improving_count", 0) or 0) + 1
        if spread_tightened or sports_edge_after_cost <= 0.0:
            ticker_bucket["clv_decaying_count"] = int(ticker_bucket.get("clv_decaying_count", 0) or 0) + 1
            family_bucket["clv_decaying_count"] = int(family_bucket.get("clv_decaying_count", 0) or 0) + 1
        if favorable_after_near_pass:
            ticker_bucket["clv_recovered_after_near_pass_count"] = int(ticker_bucket.get("clv_recovered_after_near_pass_count", 0) or 0) + 1
            family_bucket["clv_recovered_after_near_pass_count"] = int(family_bucket.get("clv_recovered_after_near_pass_count", 0) or 0) + 1
        harvest_watchlist_bucket = self._get_sports_harvest_watchlist_bucket("sports_harvest_watchlist_by_ticker", f"ticker:{ticker}")
        harvest_family_bucket = self._get_sports_harvest_watchlist_bucket("sports_harvest_watchlist_by_family", f"family:{family}")
        harvest_watchlist_bucket["first_seen_time"] = harvest_watchlist_bucket.get("first_seen_time") or now
        harvest_watchlist_bucket["last_seen_time"] = now
        harvest_watchlist_bucket["ticker"] = ticker
        harvest_watchlist_bucket["family"] = family
        harvest_family_bucket["first_seen_time"] = harvest_family_bucket.get("first_seen_time") or now
        harvest_family_bucket["last_seen_time"] = now
        harvest_family_bucket["ticker"] = ticker
        harvest_family_bucket["family"] = family
        harvest_watchlist_bucket["scan_count"] = int(harvest_watchlist_bucket.get("scan_count", 0) or 0) + 1
        harvest_family_bucket["scan_count"] = int(harvest_family_bucket.get("scan_count", 0) or 0) + 1
        previous_edge_value = self.to_float(harvest_watchlist_bucket.get("latest_edge_after_cost"), -1.0)
        improvement_delta = round(sports_edge_after_cost - previous_edge_value, 4)
        near_harvest = bool(
            -0.03 <= sports_edge_after_cost <= 0.0
            and spread_bucket in {"ultra_tight", "tight"}
            and sports_score >= 0.70
            and self._clamp(self.to_float(sports_context.get("quote_stability_trend"), 0.0), 0.0, 1.0) >= 0.55
            and self._clamp(self.to_float(sports_context.get("liquidity_quality"), 0.0), 0.0, 1.0) >= 0.50
            and self._clamp(self.to_float(sports_context.get("calibrated_probability"), 0.0), 0.0, 1.0) >= 0.50
        )
        improving_harvest = bool(
            harvest_watchlist_bucket.get("scan_count", 0) and previous_edge_value > -0.999 and improvement_delta > 0.002
        )
        if near_harvest:
            harvest_watchlist_bucket["near_harvest_count"] = int(harvest_watchlist_bucket.get("near_harvest_count", 0) or 0) + 1
            harvest_family_bucket["near_harvest_count"] = int(harvest_family_bucket.get("near_harvest_count", 0) or 0) + 1
            harvest_watchlist_bucket["latest_state"] = "near_harvest"
            harvest_family_bucket["latest_state"] = "near_harvest"
            harvest_watchlist_bucket["latest_reason"] = "negative_but_close"
            harvest_family_bucket["latest_reason"] = "negative_but_close"
            print("[LIVE-SPORTS-NEAR-HARVEST] " + json.dumps({
                "ticker": ticker,
                "family": family,
                "score": round(sports_score, 4),
                "sports_edge_after_cost": round(sports_edge_after_cost, 4),
                "spread_bucket": spread_bucket,
                "dynamic_buffer": round(sports_dynamic_buffer, 4),
                "no_vig_probability": round(no_vig_probability, 4),
                "calibrated_probability": round(calibrated_probability, 4),
                "liquidity_quality": round(self.to_float(sports_context.get("liquidity_quality"), 0.0), 4),
                "minutes_to_event": self.get_minutes_to_event(market),
                "reason": "negative_edge_but_ultra_tight_or_tight_and_stable",
            }, sort_keys=True, default=str))
        if improving_harvest:
            harvest_watchlist_bucket["improving_count"] = int(harvest_watchlist_bucket.get("improving_count", 0) or 0) + 1
            harvest_family_bucket["improving_count"] = int(harvest_family_bucket.get("improving_count", 0) or 0) + 1
            harvest_watchlist_bucket["latest_state"] = "improving_watch"
            harvest_family_bucket["latest_state"] = "improving_watch"
            harvest_watchlist_bucket["latest_reason"] = "edge_improving"
            harvest_family_bucket["latest_reason"] = "edge_improving"
            print("[LIVE-SPORTS-HARVEST-IMPROVING] " + json.dumps({
                "ticker": ticker,
                "family": family,
                "previous_edge_after_cost": round(previous_edge_value, 4),
                "current_edge_after_cost": round(sports_edge_after_cost, 4),
                "improvement_delta": improvement_delta,
                "scan_count": int(harvest_watchlist_bucket.get("scan_count", 0) or 0),
                "age_seconds": round(now - float(harvest_watchlist_bucket.get("first_seen_time") or now), 2),
            }, sort_keys=True, default=str))
        harvest_watchlist_bucket["latest_edge_after_cost"] = sports_edge_after_cost
        harvest_watchlist_bucket["latest_score"] = sports_score
        harvest_watchlist_bucket["latest_spread_bucket"] = spread_bucket
        harvest_watchlist_bucket["best_edge_after_cost"] = max(self.to_float(harvest_watchlist_bucket.get("best_edge_after_cost"), -1.0), sports_edge_after_cost)
        harvest_watchlist_bucket["best_score"] = max(self.to_float(harvest_watchlist_bucket.get("best_score"), 0.0), sports_score)
        harvest_watchlist_bucket["best_spread_bucket"] = spread_bucket if sports_edge_after_cost >= self.to_float(harvest_watchlist_bucket.get("best_edge_after_cost"), -1.0) else harvest_watchlist_bucket.get("best_spread_bucket")
        harvest_family_bucket["latest_edge_after_cost"] = sports_edge_after_cost
        harvest_family_bucket["latest_score"] = sports_score
        harvest_family_bucket["latest_spread_bucket"] = spread_bucket
        harvest_family_bucket["best_edge_after_cost"] = max(self.to_float(harvest_family_bucket.get("best_edge_after_cost"), -1.0), sports_edge_after_cost)
        harvest_family_bucket["best_score"] = max(self.to_float(harvest_family_bucket.get("best_score"), 0.0), sports_score)
        harvest_family_bucket["best_spread_bucket"] = spread_bucket if sports_edge_after_cost >= self.to_float(harvest_family_bucket.get("best_edge_after_cost"), -1.0) else harvest_family_bucket.get("best_spread_bucket")
        harvest_watchlist_bucket["last_summary"] = {
            "ticker": ticker,
            "family": family,
            "latest_state": harvest_watchlist_bucket.get("latest_state"),
            "latest_reason": harvest_watchlist_bucket.get("latest_reason"),
            "latest_edge_after_cost": round(sports_edge_after_cost, 4),
            "best_edge_after_cost": round(self.to_float(harvest_watchlist_bucket.get("best_edge_after_cost"), 0.0), 4),
            "best_score": round(self.to_float(harvest_watchlist_bucket.get("best_score"), 0.0), 4),
            "best_spread_bucket": harvest_watchlist_bucket.get("best_spread_bucket"),
            "scan_count": int(harvest_watchlist_bucket.get("scan_count", 0) or 0),
            "near_harvest_count": int(harvest_watchlist_bucket.get("near_harvest_count", 0) or 0),
            "improving_count": int(harvest_watchlist_bucket.get("improving_count", 0) or 0),
        }
        harvest_family_bucket["last_summary"] = {
            "family": family,
            "latest_state": harvest_family_bucket.get("latest_state"),
            "latest_reason": harvest_family_bucket.get("latest_reason"),
            "latest_edge_after_cost": round(sports_edge_after_cost, 4),
            "best_edge_after_cost": round(self.to_float(harvest_family_bucket.get("best_edge_after_cost"), 0.0), 4),
            "best_score": round(self.to_float(harvest_family_bucket.get("best_score"), 0.0), 4),
            "best_spread_bucket": harvest_family_bucket.get("best_spread_bucket"),
            "scan_count": int(harvest_family_bucket.get("scan_count", 0) or 0),
            "near_harvest_count": int(harvest_family_bucket.get("near_harvest_count", 0) or 0),
            "improving_count": int(harvest_family_bucket.get("improving_count", 0) or 0),
        }
        watchlist_dashboard = self._build_sports_harvest_dashboard_summary()
        if sports_candidate_handoff_to_normal_validation and improving_harvest and spread_bucket in {"ultra_tight", "tight"} and self._clamp(self.to_float(sports_context.get("quote_stability_trend"), 0.0), 0.0, 1.0) >= 0.60:
            sports_harvest_rerank_boost = max(0.0015, min(0.008, improvement_delta * 0.6 + 0.001))
            harvest_watchlist_bucket["latest_state"] = "near_ready"
            harvest_family_bucket["latest_state"] = "near_ready"
            print("[LIVE-SPORTS-HARVEST-RERANK-BOOST] " + json.dumps({
                "ticker": ticker,
                "family": family,
                "boost": round(sports_harvest_rerank_boost, 4),
                "current_edge_after_cost": round(sports_edge_after_cost, 4),
                "spread_bucket": spread_bucket,
                "scan_count": int(harvest_watchlist_bucket.get("scan_count", 0) or 0),
                "reason": "stable_improving_harvest_candidate",
            }, sort_keys=True, default=str))
        else:
            sports_harvest_rerank_boost = 0.0
        self._emit_sports_harvest_activation_telemetry(
            ticker_bucket=harvest_watchlist_bucket,
            family_bucket=harvest_family_bucket,
            summary=watchlist_dashboard,
            force=bool(near_harvest or improving_harvest or sports_candidate_handoff_to_normal_validation),
        )
        ticker_bucket["latest_summary"] = {
            "ticker": ticker,
            "family": family,
            "sports_spread_bucket": spread_bucket,
            "sports_spread_calibration_bucket": calibration_bucket,
            "sports_spread_penalty": round(self.to_float(sports_context.get("sports_spread_penalty"), 0.0), 4),
            "sports_spread_adjusted_threshold": round(self.to_float(sports_context.get("sports_spread_adjusted_threshold"), 0.0), 4),
            "sports_edge_after_cost": round(sports_edge_after_cost, 4),
            "sports_edge_raw": round(self.to_float(sports_context.get("sports_edge_raw"), 0.0), 4),
            "calibrated_probability": round(calibrated_probability, 4),
            "no_vig_probability": round(no_vig_probability, 4),
            "no_vig_odds": round(no_vig_odds, 6),
            "sports_dynamic_buffer": round(sports_dynamic_buffer, 4),
            "momentum_score": round(self.to_float(sports_context.get("momentum_score"), 0.0), 4),
            "directional_bias": sports_context.get("directional_bias"),
            "directional_consistency": round(self.to_float(sports_context.get("directional_consistency"), 0.0), 4),
            "orderbook_pressure": sports_context.get("orderbook_pressure"),
            "event_urgency": sports_context.get("event_urgency"),
            "market_lifecycle_state": sports_context.get("market_lifecycle_state"),
            "yes_top_size": sports_context.get("yes_top_size"),
            "no_top_size": sports_context.get("no_top_size"),
            "open_interest": sports_context.get("open_interest"),
            "predictive_regime_score": round(self.to_float(sports_context.get("predictive_regime_score"), 0.0), 4),
            "quote_stability_trend": round(self.to_float(sports_context.get("quote_stability_trend"), 0.0), 4),
            "edge_durability_trend": round(self.to_float(sports_context.get("edge_durability_trend"), 0.0), 4),
            "family_learning_trend": round(self.to_float(sports_context.get("family_learning_trend"), 0.0), 4),
            "liquidity_quality": round(self.to_float(sports_context.get("liquidity_quality"), 0.0), 4),
            "adaptive_confidence_modifier": round(self.to_float(sports_context.get("adaptive_confidence_modifier"), 0.0), 4),
            "family_rotation_score": round(self.to_float(sports_context.get("family_rotation_score"), 0.0), 4),
            "entry_timing_fusion_score": round(self.to_float(sports_context.get("entry_timing_fusion_score"), 0.0), 4),
            "queue_state": str(sports_context.get("queue_state") or "unknown"),
            "final_sports_action": action,
            "reject_reason": reject_reason,
            "sports_candidate_handoff_to_normal_validation": bool(sports_context.get("sports_candidate_handoff_to_normal_validation")),
            "calibration_mode": sports_context.get("calibration_mode"),
            "spread_policy_used": sports_context.get("spread_policy_used"),
            "threshold_policy_used": sports_context.get("threshold_policy_used"),
            "sports_score": round(sports_score, 4),
            "best_sports_score": round(self.to_float(ticker_bucket.get("best_sports_score"), 0.0) or 0.0, 4),
            "best_sports_edge_after_cost": round(self.to_float(ticker_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, 4),
            "clv_improving_count": int(ticker_bucket.get("clv_improving_count", 0) or 0),
            "clv_decaying_count": int(ticker_bucket.get("clv_decaying_count", 0) or 0),
            "clv_recovered_after_near_pass_count": int(ticker_bucket.get("clv_recovered_after_near_pass_count", 0) or 0),
            "sports_harvest_watch_state": str(harvest_watchlist_bucket.get("latest_state") or "blocked"),
            "sports_harvest_improving_count": int(harvest_watchlist_bucket.get("improving_count", 0) or 0),
            "sports_harvest_near_harvest_count": int(harvest_watchlist_bucket.get("near_harvest_count", 0) or 0),
            "sports_harvest_rerank_boost": round(self.to_float(sports_harvest_rerank_boost, 0.0), 4),
        }
        ticker_bucket["score_history"].append(sports_score)
        ticker_bucket["action_history"].append(action)
        ticker_bucket["blocker_history"].append(reject_reason)
        if action == "allow_normal_validation":
            ticker_bucket["allow_normal_validation_count"] = int(ticker_bucket.get("allow_normal_validation_count", 0) or 0) + 1
            family_bucket["allow_normal_validation_count"] = int(family_bucket.get("allow_normal_validation_count", 0) or 0) + 1
        elif action == "near_pass":
            ticker_bucket["near_pass_count"] = int(ticker_bucket.get("near_pass_count", 0) or 0) + 1
            family_bucket["near_pass_count"] = int(family_bucket.get("near_pass_count", 0) or 0) + 1
        if reject_reason == "spread_above_hard_limit":
            ticker_bucket["rejected_wide_spread"] = int(ticker_bucket.get("rejected_wide_spread", 0) or 0) + 1
            family_bucket["rejected_wide_spread"] = int(family_bucket.get("rejected_wide_spread", 0) or 0) + 1
        elif reject_reason == "edge_below_cost":
            ticker_bucket["rejected_edge_below_cost"] = int(ticker_bucket.get("rejected_edge_below_cost", 0) or 0) + 1
            family_bucket["rejected_edge_below_cost"] = int(family_bucket.get("rejected_edge_below_cost", 0) or 0) + 1
        elif reject_reason == "flat_directional_bias":
            ticker_bucket["rejected_flat_bias"] = int(ticker_bucket.get("rejected_flat_bias", 0) or 0) + 1
            family_bucket["rejected_flat_bias"] = int(family_bucket.get("rejected_flat_bias", 0) or 0) + 1
        elif reject_reason == "missing_quotes":
            ticker_bucket["rejected_missing_quotes"] = int(ticker_bucket.get("rejected_missing_quotes", 0) or 0) + 1
            family_bucket["rejected_missing_quotes"] = int(family_bucket.get("rejected_missing_quotes", 0) or 0) + 1
        elif reject_reason == "weak_liquidity":
            ticker_bucket["rejected_weak_liquidity"] = int(ticker_bucket.get("rejected_weak_liquidity", 0) or 0) + 1
            family_bucket["rejected_weak_liquidity"] = int(family_bucket.get("rejected_weak_liquidity", 0) or 0) + 1
        elif reject_reason == "decaying_regime":
            ticker_bucket["rejected_decaying_regime"] = int(ticker_bucket.get("rejected_decaying_regime", 0) or 0) + 1
            family_bucket["rejected_decaying_regime"] = int(family_bucket.get("rejected_decaying_regime", 0) or 0) + 1
        ticker_bucket["last_summary"] = {
            **ticker_bucket["latest_summary"],
            "total_sports_scanned": int(ticker_bucket.get("total_sports_scanned", 0) or 0),
            "rejected_wide_spread": int(ticker_bucket.get("rejected_wide_spread", 0) or 0),
            "rejected_edge_below_cost": int(ticker_bucket.get("rejected_edge_below_cost", 0) or 0),
            "rejected_flat_bias": int(ticker_bucket.get("rejected_flat_bias", 0) or 0),
            "rejected_missing_quotes": int(ticker_bucket.get("rejected_missing_quotes", 0) or 0),
            "rejected_weak_liquidity": int(ticker_bucket.get("rejected_weak_liquidity", 0) or 0),
            "rejected_decaying_regime": int(ticker_bucket.get("rejected_decaying_regime", 0) or 0),
            "near_pass_count": int(ticker_bucket.get("near_pass_count", 0) or 0),
            "allow_normal_validation_count": int(ticker_bucket.get("allow_normal_validation_count", 0) or 0),
            "best_sports_edge_after_cost": round(self.to_float(ticker_bucket.get("best_sports_edge_after_cost"), 0.0) or 0.0, 4),
            "best_sports_score": round(self.to_float(ticker_bucket.get("best_sports_score"), 0.0) or 0.0, 4),
        }
        family_bucket["last_summary"] = self._build_sports_market_calibration_family_summary(family=family)
        self.last_sports_harvest_summary = dict(ticker_bucket["last_summary"])
        self.last_sports_harvest_family_summary = dict(family_bucket.get("last_summary") or {})
        self.last_sports_harvest_overall_summary = self._build_sports_market_calibration_overall_summary()
        self._emit_sports_market_calibration_telemetry(
            ticker_bucket=ticker_bucket,
            family_bucket=family_bucket,
            force=force or action == "allow_normal_validation" or reject_reason in {"spread_above_hard_limit", "edge_below_cost", "missing_quotes", "weak_liquidity", "decaying_regime", "flat_directional_bias"},
        )
        return ticker_bucket["last_summary"], {
            "sports_spread_bucket": spread_bucket,
            "sports_spread_penalty": self.to_float(sports_context.get("sports_spread_penalty"), 0.0),
            "sports_spread_adjusted_threshold": self.to_float(sports_context.get("sports_spread_adjusted_threshold"), 0.0),
            "sports_edge_after_cost": sports_edge_after_cost,
            "sports_candidate_handoff_to_normal_validation": bool(sports_context.get("sports_candidate_handoff_to_normal_validation")),
            "final_sports_action": action,
            "reject_reason": reject_reason,
            "sports_score": round(sports_score, 4),
            "sports_harvest_watch_state": str(harvest_watchlist_bucket.get("latest_state") or "blocked"),
            "sports_harvest_improving_count": int(harvest_watchlist_bucket.get("improving_count", 0) or 0),
            "sports_harvest_near_harvest_count": int(harvest_watchlist_bucket.get("near_harvest_count", 0) or 0),
            "sports_harvest_rerank_boost": round(self.to_float(sports_harvest_rerank_boost, 0.0), 4),
        }

    def _topbook_reject_reason(self, yes_price=None, yes_size=None, no_price=None, no_size=None, spread=None, max_spread=None):
        if yes_price is None and no_price is None and yes_size in (None, 0.0) and no_size in (None, 0.0):
            return "missing_prices_and_sizes"
        if yes_price is None:
            return "missing_yes_price"
        if no_price is None:
            return "missing_no_price"
        if yes_size is None:
            return "missing_yes_size"
        if no_size is None:
            return "missing_no_size"
        if (yes_size or 0.0) <= 0.0 and (no_size or 0.0) <= 0.0:
            return "zero_yes_no_sizes"
        if (yes_size or 0.0) <= 0.0:
            return "zero_yes_size"
        if (no_size or 0.0) <= 0.0:
            return "zero_no_size"
        spread_limit = MAX_ENTRY_SPREAD if max_spread is None else max_spread
        if spread is not None and (spread < 0.0 or spread > spread_limit):
            return "spread_outside_allowed_range"
        return "converted"

    def _emit_topbook_trace(self, prefix, market=None, family=None, reason=None, **fields):
        market = market if isinstance(market, dict) else {}
        family = family or self.get_market_family(market)
        if not self._is_sports_market_or_family(family) and family != "KXBTC15M":
            return
        ticker = str(fields.pop("ticker", "") or market.get("ticker", "") or "").strip()
        quote_values = self.get_market_quote_values(market) if market else {}
        yes_bid = fields.pop("yes_bid", quote_values.get("yes_bid"))
        yes_ask = fields.pop("yes_ask", quote_values.get("yes_ask"))
        no_bid = fields.pop("no_bid", quote_values.get("no_bid"))
        no_ask = fields.pop("no_ask", quote_values.get("no_ask"))
        spread = fields.pop("spread", None)
        if spread is None and yes_bid is not None and yes_ask is not None:
            try:
                spread = round(float(yes_ask) - float(yes_bid), 4)
            except (TypeError, ValueError):
                spread = None
        detected_fields = fields.pop("detected_fields", None)
        if detected_fields is None:
            detected_fields = self._get_raw_liquidity_candidate_fields(market)
        extras = " ".join(f"{key}={value}" for key, value in fields.items() if value is not None)
        print(
            f"{prefix} ticker={ticker} family={family} raw_payload_keys={self._safe_payload_keys(market)} "
            f"detected_fields={detected_fields} yes_bid={yes_bid} yes_ask={yes_ask} no_bid={no_bid} no_ask={no_ask} "
            f"yes_price={fields.get('yes_price')} no_price={fields.get('no_price')} "
            f"yes_size={fields.get('yes_size')} no_size={fields.get('no_size')} "
            f"spread={spread} liquidity={market.get('liquidity_dollars', market.get('liquidity'))} "
            f"exact_reject_reason={reason or 'none'}"
            f"{' ' + extras if extras else ''}"
        )

    def _record_live_reject_telemetry(self, *, reason, ticker=None, family=None, spread=None, stage=None, category=None, details=None):
        self._record_execution_failure_audit(reason=reason, stage=stage, category=category)
        collector = getattr(self, "live_reject_telemetry", None)
        if collector is not None:
            collector.record_reject(
                reason=reason,
                ticker=ticker,
                family=family,
                spread=spread,
                stage=stage,
                category=category,
                details=details,
            )
        queue_details = details if isinstance(details, dict) else {}
        queue_ticker = str(ticker or queue_details.get("ticker") or queue_details.get("market_ticker") or "").strip()
        queue_family = str(family or queue_details.get("family") or queue_details.get("market_family") or "").strip().upper() or "UNKNOWN"
        predictive_builder = getattr(self, "_build_predictive_regime_family_summary", None)
        confidence_builder = getattr(self, "_build_adaptive_confidence_family_summary", None)
        rotation_builder = getattr(self, "_build_family_rotation_family_summary", None)
        learning_builder = getattr(self, "_build_candidate_learning_family_summary", None)
        microstructure_builder = getattr(self, "_build_live_microstructure_family_summary", None)
        reactivation_summary = getattr(self, "last_reactivation_family_summary", {}) or {}
        predictive_summary = predictive_builder(family=queue_family) if callable(predictive_builder) else {}
        confidence_summary = confidence_builder(family=queue_family) if callable(confidence_builder) else {}
        rotation_summary = rotation_builder(family=queue_family) if callable(rotation_builder) else {}
        learning_summary = learning_builder(family=queue_family) if callable(learning_builder) else {}
        microstructure_summary = microstructure_builder(family=queue_family) if callable(microstructure_builder) else {}
        self._update_safe_opportunity_queue(
            ticker=queue_ticker,
            family=queue_family,
            event_type="reject",
            reason=reason,
            spread=spread,
            predictive_regime_summary=predictive_summary,
            adaptive_confidence_summary=confidence_summary,
            family_rotation_summary=rotation_summary,
            learning_summary=learning_summary,
            family_learning_summary=learning_summary,
            family_microstructure_summary=microstructure_summary,
            reactivation_summary=reactivation_summary,
            details=queue_details,
        )

