                    candidates_passing_adaptive_spread=len(strict_pool),
                    candidates_passing_momentum=0,
                    candidates_reaching_phase55=0,
                    candidates_blocked_by_execution_safety=0,
                    candidate_records=[],
                    best_prefilter_candidate=trade_readiness_best_prefilter_candidate,
                    prefilter_reject_reason_counts=prefilter_reject_reason_counts,
                    strict_reject_reason_counts={reason: count for (reason, _family), count in strict_rejects.items()},
                    decision_skip_reasons={},
                    activation_denial_counts=activation_denial_counts,
